-- 0059_wave_e_delta_metrics_behavior.sql -- generic Wave E delta behaviour.
-- Applies after 0058_wave_e_delta_metrics.sql. The timeout is precautionary.
set local statement_timeout='20min';
create temp table _delta_behavior_pre(k text primary key,v text not null) on commit drop;
insert into _delta_behavior_pre values('session_user',session_user),('current_user',current_user);

-- Tables/functions born in the base are migration-role owned. Widen the exact public read/call
-- surface before switching; every body below is owned by clara_fn_owner.
reset role;
grant execute on function clara.create_account_set_v1(uuid,text,text,jsonb,boolean,date,text),
 clara.mint_metric_input_snapshot_v1(uuid,uuid[],text) to clara_authenticated;
do $agent$ declare n text;v_nullable boolean;begin foreach n in array array['metric_definitions','metric_definition_versions','account_sets','account_set_versions','presentation_maps','presentation_map_versions','metric_constants','edge_policy_sets','metric_edge_policies'] loop select is_nullable='YES' into strict v_nullable from information_schema.columns where table_schema='clara'and table_name=n and column_name='firm_id';execute format('create policy p_delta_agent_catalog on clara.%I for select to clara_agent_ro using(%s)',n,case when v_nullable then'firm_id is null or firm_id=clara.wake_firm()'else'firm_id=clara.wake_firm()'end);execute format('grant select on clara.%I to clara_agent_ro',n);end loop;end $agent$;
set role clara_fn_owner;

