insert into clara.metric_temporalities(temporality_key) values('point_in_time'),('flow'),('period_average');
insert into clara.metric_primitives(primitive_key,structural_integer_fields) values('measure','{}'),('sum','{}'),('average','{}'),('lag','{periods}'),('subtract','{}'),('divide','{}'),('days_in_period','{}'),('percent_change','{}'),('multiply','{}'),('constant','{}'),('count','{}');
insert into clara.metric_na_reason_versions(reason_key,version,cell_status,display_token,semantics,effective_from) values
 ('divide_by_zero',1,'undefined','—','{"policy":"undefined_cell"}','2020-01-01'),('negative_denominator',1,'undefined','—','{"policy":"signed_ratio_refuse"}','2020-01-01'),('absent',1,'absent','—','{"policy":"absent_is_absent"}','2020-01-01'),('prior_period_absent',1,'absent','—','{"fix":"mint or snapshot the missing calendar-prior period"}','2020-01-01'),('account_set_drift',1,'refused','—','{"fix":"mint a new account-set version"}','2020-01-01'),('account_set_resolution_absent',1,'refused','—','{"fix":"publish one account-set version whose effective window covers the target period"}','2020-01-01'),('account_set_resolution_ambiguous',1,'refused','—','{"fix":"repair the account-set effective windows so exactly one version covers the target period"}','2020-01-01'),('account_set_expansion',1,'refused','—','{"fix":"narrow the account-set selector and mint a new version with at most 512 frozen members"}','2020-01-01'),('sign_presentation_mismatch',1,'refused','—','{"fix":"use natural presentation or match positive_expense to expense and positive_revenue to income accounts"}','2020-01-01');
with s as(insert into clara.edge_policy_sets(policy_set_key,version,effective_from,content_sha256)values('eps_v1',1,'2020-01-01',clara._hash('{"version":1}'::jsonb))returning id)insert into clara.metric_edge_policies(policy_set_id,policy_class,policy_key,semantics)select id,c,k,j from s cross join(values('division_by_zero','undefined_cell','{"status":"undefined","reason":"divide_by_zero"}'::jsonb),('negative_denominator','signed_ratio_refuse','{"reason":"negative_denominator","opt_in":"allow_negative"}'::jsonb),('missing_data','absent_is_absent','{"status":"absent","zero_when_no_rows":true}'::jsonb),('sign_normalization','natural_then_declared','{"once":"measure_leaf","modes":["natural","positive_expense","positive_revenue"]}'::jsonb),('rounding','half_up_once_at_declared_scale','{"method":"half-away-from-zero","round_once":true}'::jsonb))x(c,k,j);
