-- Narrow lifecycle transitions replace the generic append-only walls.
drop trigger t_metricdefinitionversions_append_only on clara.metric_definition_versions;
create function clara._tf_metric_definition_lifecycle_v1()returns trigger language plpgsql security definer set search_path=clara,pg_temp as $$begin if tg_op='DELETE'or(to_jsonb(new)-array['state','approved_by','approved_at','approval_reason','self_approval_attestation','approved_formula_sha256','approval_evidence','supersedes_version_id'])is distinct from(to_jsonb(old)-array['state','approved_by','approved_at','approval_reason','self_approval_attestation','approved_formula_sha256','approval_evidence','supersedes_version_id'])then raise exception 'metric definition version is historical'using errcode='CLR08';end if;if old.state='draft'and new.state='firm_approved'then if new.approved_by is null or new.approved_at is null or nullif(btrim(new.approval_reason),'')is null or new.approved_formula_sha256 is distinct from new.formula_sha256 or not(new.approval_evidence@>'{"kind":"human_approval","version":1}'::jsonb)then raise exception 'approved definition transition lacks positive evidence'using errcode='CLR16';end if;elsif old.state='draft'and new.state='rejected'then if new.approved_by is not null or new.approved_at is not null or new.approved_formula_sha256 is not null or nullif(btrim(new.approval_reason),'')is null then raise exception 'rejected definition transition is malformed'using errcode='CLR16';end if;elsif old.state in('firm_approved','canonical')and new.state='superseded'then if nullif(btrim(new.approval_reason),'')is null or new.approved_formula_sha256 is distinct from old.approved_formula_sha256 then raise exception 'superseded definition transition is malformed'using errcode='CLR16';end if;elsif old.state='firm_approved'and new.state=old.state and old.supersedes_version_id is null and new.supersedes_version_id is not null then if row(new.approved_by,new.approved_at,new.approval_reason,new.self_approval_attestation,new.approved_formula_sha256,new.approval_evidence)is distinct from row(old.approved_by,old.approved_at,old.approval_reason,old.self_approval_attestation,old.approved_formula_sha256,old.approval_evidence)then raise exception 'successor lineage binding changed approval evidence'using errcode='CLR16';end if;else raise exception 'illegal metric definition transition'using errcode='CLR16';end if;return new;end$$;
revoke all on function clara._tf_metric_definition_lifecycle_v1()from public;create trigger t_metricdefinitionversions_lifecycle before update or delete on clara.metric_definition_versions for each row execute function clara._tf_metric_definition_lifecycle_v1();

-- Closed recursive validator returns dimension vector, temporality, symbolic period and static costs.
create function clara._validate_metric_node_v1(n jsonb,d int default 1)returns jsonb language plpgsql stable security definer set search_path=clara,pg_temp as $$
declare k text;a jsonb;b jsonb;r jsonb;x jsonb;first boolean:=true;nodes int:=1;leaves int:=0;lagmax int:=0;po int:=0;cp int;dp int;np int;cnt int;
begin if n is null or jsonb_typeof(n)<>'object'or not(n?'node')or jsonb_typeof(n->'node')<>'string'or nullif(n->>'node','')is null then raise exception 'metric node malformed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use the closed allowed node fields and supply a nonblank node"}';end if;k:=n->>'node';if k='literal'or n?'value'then raise exception 'numeric literal forbidden'using errcode='CLR10',detail='{"reason":"numeric_literal_forbidden","fix":"use an approved versioned constant"}';end if;if d>12 then raise exception 'metric cost exceeded'using errcode='CLR10',detail='{"reason":"cost_exceeded","class":"depth","limit":12,"fix":"reduce metric nesting to at most 12 levels"}';end if;
 if k='measure'then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','set','aspect','present_as','scope']))or not(n?'set')or jsonb_typeof(n->'set')<>'object'or not(n?'aspect')or jsonb_typeof(n->'aspect')<>'string'or not(n?'scope')or jsonb_typeof(n->'scope')<>'object'or(n?'present_as'and jsonb_typeof(n->'present_as')<>'string')or n#>>'{set,kind}'<>'account_set'or nullif(n#>>'{set,key}','')is null or exists(select 1 from jsonb_object_keys(n->'set')q where q<>all(array['key','kind']))or exists(select 1 from jsonb_object_keys(n->'scope')q where q<>all(array['period','entity','basis']))or not(n->'scope'?'period')or jsonb_typeof(n#>'{scope,period}')<>'string'or not(n->'scope'?'entity')or jsonb_typeof(n#>'{scope,entity}')<>'string'or not(n->'scope'?'basis')or jsonb_typeof(n#>'{scope,basis}')<>'string'then raise exception 'measure schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"remove fields outside the closed measure schema; sign presentation is leaf-only"}';end if;if n#>>'{scope,entity}'<>'$CLIENT'or n#>>'{scope,basis}'<>'accrual'or n#>>'{scope,period}'!~'^\$P(0|-[1-9][0-9]?)$'or n->>'aspect'not in('period_movement','closing_balance')or coalesce(n->>'present_as','natural')not in('natural','positive_expense','positive_revenue')then raise exception 'measure scope mismatch'using errcode='CLR10',detail='{"reason":"scope_mismatch","fix":"use a single client entity, accrual basis and bound period"}';end if;po:=case when n#>>'{scope,period}'='$P0'then 0 else -substring(n#>>'{scope,period}'from 4)::int end;r:=jsonb_build_object('cp',1,'dp',0,'np',0,'temp',case when n->>'aspect'='closing_balance'then'point_in_time'else'flow'end,'po',po,'nodes',1,'leaves',1,'lag',abs(po));
 elsif k='constant'then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','key']))or not(n?'key')or jsonb_typeof(n->'key')<>'string'or nullif(n->>'key','')is null then raise exception 'constant schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use only node and key"}';end if;select min(currency_power),min(days_power),min(count_power),count(distinct concat_ws(':',currency_power,days_power,count_power))into cp,dp,np,cnt from clara.metric_constants where constant_key=n->>'key';if cnt<>1 then raise exception 'constant absent or ambiguous'using errcode='CLR10',detail='{"reason":"scope_mismatch","fix":"publish one versioned constant dimension"}';end if;r:=jsonb_build_object('cp',cp,'dp',dp,'np',np,'temp','flow','po',0,'nodes',1,'leaves',0,'lag',0);
 elsif k='days_in_period'then if exists(select 1 from jsonb_object_keys(n)q where q<>'node')then raise exception 'days schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use only node"}';end if;r:='{"cp":0,"dp":1,"np":0,"temp":"flow","po":0,"nodes":1,"leaves":0,"lag":0}';
 elsif k='count'then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','source','scope','domain','item_kind','operation_kind']))or not(n?'source')or jsonb_typeof(n->'source')<>'string'or not(n?'scope')or jsonb_typeof(n->'scope')<>'object'or exists(select 1 from jsonb_object_keys(n->'scope')q where q<>all(array['period','entity','basis']))or not(n->'scope'?'period')or jsonb_typeof(n#>'{scope,period}')<>'string'or not(n->'scope'?'entity')or jsonb_typeof(n#>'{scope,entity}')<>'string'or not(n->'scope'?'basis')or jsonb_typeof(n#>'{scope,basis}')<>'string'or(n?'domain'and jsonb_typeof(n->'domain')<>'string')or(n?'item_kind'and jsonb_typeof(n->'item_kind')<>'string')or(n?'operation_kind'and jsonb_typeof(n->'operation_kind')<>'string')or n->>'source'not in('open_items','allocations','contributions','samples')or n#>>'{scope,entity}'<>'$CLIENT'or n#>>'{scope,basis}'<>'accrual'or n#>>'{scope,period}'!~'^\$P(0|-[1-9][0-9]?)$'or(n?'domain'and n->>'source'not in('open_items','allocations'))or(n?'item_kind'and n->>'source'<>'open_items')or(n?'operation_kind'and n->>'source'<>'allocations')then raise exception 'count scope mismatch'using errcode='CLR10',detail='{"reason":"scope_mismatch","fix":"use a closed immutable-fact source and client scope"}';end if;po:=case when n#>>'{scope,period}'='$P0'then 0 else -substring(n#>>'{scope,period}'from 4)::int end;r:=jsonb_build_object('cp',0,'dp',0,'np',1,'temp','flow','po',po,'nodes',1,'leaves',0,'lag',abs(po));
 elsif k='lag'then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','periods','of']))or not(n?'periods')or jsonb_typeof(n->'periods')<>'number'or not(n?'of')or jsonb_typeof(n->'of')<>'object'or(n->>'periods')::numeric<>trunc((n->>'periods')::numeric)or(n->>'periods')::int not between 1 and 24 then raise exception 'metric lag cost exceeded'using errcode='CLR10',detail='{"reason":"cost_exceeded","class":"lag","limit":24,"fix":"reduce the largest lag to at most 24 periods"}';end if;a:=clara._validate_metric_node_v1(n->'of',d+1);lagmax:=(a->>'lag')::int+(n->>'periods')::int;r:=a||jsonb_build_object('po',(a->>'po')::int-(n->>'periods')::int,'nodes',(a->>'nodes')::int+1,'lag',lagmax);
 elsif k='average'and n?'of'then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','of']))or jsonb_typeof(n->'of')<>'object'then raise exception 'average schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use only node and an object operand"}';end if;a:=clara._validate_metric_node_v1(n->'of',d+1);if a->>'temp'<>'point_in_time'then raise exception 'average temporality mismatch'using errcode='CLR10',detail='{"reason":"temporality_mismatch","fix":"average(of) samples a point-in-time value"}';end if;r:=a||jsonb_build_object('temp','period_average','nodes',(a->>'nodes')::int+1);
 elsif k in('sum','average')then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','terms']))or jsonb_typeof(n->'terms')<>'array'or jsonb_array_length(n->'terms')<1 then raise exception 'aggregate schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"remove non-node aggregate fields such as present_as; sign presentation is allowed only at a measure leaf, and use a non-empty terms array"}';end if;for x in select value from jsonb_array_elements(n->'terms')loop a:=clara._validate_metric_node_v1(x,d+1);if not first and row(r->>'cp',r->>'dp',r->>'np')<>row(a->>'cp',a->>'dp',a->>'np')then raise exception 'dimension mismatch'using errcode='CLR10',detail='{"reason":"dimension_mismatch","fix":"use matching operands"}';end if;if not first and(r->>'temp'<>a->>'temp'or r->>'po'<>a->>'po')then raise exception 'temporality mismatch'using errcode='CLR10',detail='{"reason":"temporality_mismatch","fix":"align periods and wrap stock legs in average"}';end if;if first then r:=a;first:=false;end if;nodes:=nodes+(a->>'nodes')::int;leaves:=leaves+(a->>'leaves')::int;lagmax:=greatest(lagmax,(a->>'lag')::int);end loop;r:=r||jsonb_build_object('temp',case when k='average'then'period_average'else r->>'temp'end,'nodes',nodes,'leaves',leaves,'lag',lagmax);
 elsif k in('divide','subtract','multiply','percent_change')then if k='percent_change'then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','current','prior']))or not(n?'current')or jsonb_typeof(n->'current')<>'object'or not(n?'prior')or jsonb_typeof(n->'prior')<>'object'then raise exception 'binary schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use required object operands current and prior"}';end if;a:=clara._validate_metric_node_v1(n->'current',d+1);b:=clara._validate_metric_node_v1(n->'prior',d+1);else if exists(select 1 from jsonb_object_keys(n)q where q<>all(case when k='divide'then array['node','num','den']else array['node','left','right']end))or(k='divide'and(not(n?'num')or jsonb_typeof(n->'num')<>'object'or not(n?'den')or jsonb_typeof(n->'den')<>'object'))or(k<>'divide'and(not(n?'left')or jsonb_typeof(n->'left')<>'object'or not(n?'right')or jsonb_typeof(n->'right')<>'object'))then raise exception 'binary schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"supply both required object operands and remove fields outside the closed binary schema"}';end if;a:=clara._validate_metric_node_v1(case when k='divide'then n->'num'else n->'left'end,d+1);b:=clara._validate_metric_node_v1(case when k='divide'then n->'den'else n->'right'end,d+1);end if;if k='subtract'and row(a->>'cp',a->>'dp',a->>'np',a->>'temp',a->>'po')<>row(b->>'cp',b->>'dp',b->>'np',b->>'temp',b->>'po')then raise exception 'subtract mismatch'using errcode='CLR10',detail='{"reason":"dimension_mismatch","fix":"use matching operands at the same period and temporality"}';end if;if k='percent_change'and row(a->>'cp',a->>'dp',a->>'np')<>row(b->>'cp',b->>'dp',b->>'np')then raise exception 'percent-change dimension mismatch'using errcode='CLR10',detail='{"reason":"dimension_mismatch","fix":"compare like with like: percent_change subtracts its prior from its current, so both operands must carry the same dimension"}';end if;if k in('divide','percent_change')and a->>'temp'='point_in_time'and b->>'temp'='flow'then raise exception 'stock over flow'using errcode='CLR10',detail='{"reason":"stock_over_flow","fix":"average(...) the numerator, then multiply by days_in_period"}';end if;if k in('divide','percent_change')and a->>'temp'<>b->>'temp'and not((a->>'temp'='period_average'and b->>'temp'='flow')or(a->>'temp'='flow'and b->>'temp'='period_average'))then raise exception 'temporality mismatch'using errcode='CLR10',detail='{"reason":"temporality_mismatch","fix":"align operand temporalities or average a point-in-time numerator against the flow"}';end if;if k='multiply'and not((a->>'temp'=b->>'temp')or(a->>'temp'='flow'and b->>'temp'='period_average')or(a->>'temp'='period_average'and b->>'temp'='flow'))then raise exception 'temporality mismatch'using errcode='CLR10',detail='{"reason":"temporality_mismatch","fix":"multiply values with a compatible period temporality"}';end if;cp:=case when k in('divide','percent_change')then(a->>'cp')::int-(b->>'cp')::int when k='multiply'then(a->>'cp')::int+(b->>'cp')::int else(a->>'cp')::int end;dp:=case when k in('divide','percent_change')then(a->>'dp')::int-(b->>'dp')::int when k='multiply'then(a->>'dp')::int+(b->>'dp')::int else(a->>'dp')::int end;np:=case when k in('divide','percent_change')then(a->>'np')::int-(b->>'np')::int when k='multiply'then(a->>'np')::int+(b->>'np')::int else(a->>'np')::int end;if abs(cp)>1 then raise exception 'dimension overflow'using errcode='CLR10',detail='{"reason":"dimension_overflow","fix":"do not multiply currency by currency"}';end if;r:=jsonb_build_object('cp',cp,'dp',dp,'np',np,'temp',case when k='subtract'then a->>'temp'when k='multiply'and a->>'temp'=b->>'temp'then a->>'temp'when k='divide'and a->>'temp'=b->>'temp'then a->>'temp'else'flow'end,'po',(a->>'po')::int,'nodes',(a->>'nodes')::int+(b->>'nodes')::int+1,'leaves',(a->>'leaves')::int+(b->>'leaves')::int,'lag',greatest((a->>'lag')::int,(b->>'lag')::int));
 else raise exception 'metric primitive unknown'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use a registered closed primitive"}';end if;if(r->>'nodes')::int>64 or(r->>'leaves')::int>32 or(r->>'lag')::int>24 then raise exception 'metric cost exceeded'using errcode='CLR10',detail=jsonb_build_object('reason','cost_exceeded','class',case when(r->>'nodes')::int>64 then'nodes'when(r->>'leaves')::int>32 then'leaves'else'lag'end,'node_limit',64,'measure_limit',32,'lag_limit',24,'fix',case when(r->>'nodes')::int>64 then'reduce the AST to at most 64 nodes'when(r->>'leaves')::int>32 then'reduce the AST to at most 32 measure leaves'else'reduce the largest lag to at most 24 periods'end)::text;end if;return r;end$$;
revoke all on function clara._validate_metric_node_v1(jsonb,int)from public;

create function clara.validate_metric_ast_v1(a jsonb)returns jsonb language plpgsql stable security definer set search_path=clara,pg_temp as $$declare r jsonb;u record;begin if a is null or jsonb_typeof(a)<>'object'or exists(select 1 from jsonb_object_keys(a)q where q<>all(array['ast','unit','temporality','result_scale','edge_policy_set','root']))or not(a?'ast')or jsonb_typeof(a->'ast')<>'string'or a->>'ast'<>'clara.metric/v1'or not(a?'unit')or jsonb_typeof(a->'unit')<>'string'or not(a?'temporality')or jsonb_typeof(a->'temporality')<>'string'or not(a?'result_scale')or jsonb_typeof(a->'result_scale')<>'number'or not(a?'edge_policy_set')or jsonb_typeof(a->'edge_policy_set')<>'string'or nullif(a->>'edge_policy_set','')is null or not(a?'root')or jsonb_typeof(a->'root')<>'object'then raise exception 'metric top-level schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"supply exactly the six required clara.metric/v1 fields"}';end if;if jsonb_typeof(a->'result_scale')<>'number'or(a->>'result_scale')::numeric<>trunc((a->>'result_scale')::numeric)or(a->>'result_scale')::int not between 0 and 12 then raise exception 'result scale invalid'using errcode='CLR10',detail='{"reason":"cost_exceeded","class":"result_scale","limit":12,"fix":"set result_scale to an integer from 0 through 12"}';end if;if not exists(select 1 from clara.edge_policy_sets where policy_set_key=a->>'edge_policy_set'and firm_id is null)then raise exception 'edge policy absent'using errcode='CLR10',detail='{"reason":"scope_mismatch","fix":"use an effective versioned edge-policy set"}';end if;r:=clara._validate_metric_node_v1(a->'root',1);select * into u from clara.metric_units where unit_key=case a->>'unit'when'currency'then'money'else a->>'unit'end;if u.unit_key is null or row(u.currency_power,u.days_power,u.count_power)<>row((r->>'cp')::smallint,(r->>'dp')::smallint,(r->>'np')::smallint)or a->>'temporality'<>r->>'temp'then raise exception 'metric declaration mismatch'using errcode='CLR10',detail='{"reason":"declaration_mismatch","fix":"match the declared unit and temporality to the inferred contract"}';end if;return r||jsonb_build_object('unit',u.unit_key,'result_scale',(a->>'result_scale')::int);end$$;
revoke all on function clara.validate_metric_ast_v1(jsonb)from public;

-- Proposal admits a draft only after closed structural validation. Semantic/type/scope/static-cost
-- proofs remain approval-time responsibilities of validate_metric_ast_v1.
create function clara._validate_metric_ast_shape_v1(a jsonb)returns jsonb language plpgsql stable security definer set search_path=clara,pg_temp as $$
declare todo jsonb[];levels int[];n jsonb;k text;x jsonb;i int:=1;depth int;
begin
 if a is null or jsonb_typeof(a)<>'object'or exists(select 1 from jsonb_object_keys(a)q where q<>all(array['ast','unit','temporality','result_scale','edge_policy_set','root']))or not(a?'ast')or jsonb_typeof(a->'ast')<>'string'or a->>'ast'<>'clara.metric/v1'or not(a?'unit')or jsonb_typeof(a->'unit')<>'string'or nullif(a->>'unit','')is null or not(a?'temporality')or jsonb_typeof(a->'temporality')<>'string'or nullif(a->>'temporality','')is null or not(a?'result_scale')or jsonb_typeof(a->'result_scale')<>'number'or not(a?'edge_policy_set')or jsonb_typeof(a->'edge_policy_set')<>'string'or nullif(a->>'edge_policy_set','')is null or not(a?'root')or jsonb_typeof(a->'root')<>'object'then raise exception 'metric top-level schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"supply exactly the six required clara.metric/v1 fields with their registered JSON types"}';end if;
 if pg_column_size(a)>262144 then raise exception 'metric AST exceeds proposal safety ceiling'using errcode='CLR10',detail='{"reason":"structural_safety_ceiling","limit_bytes":262144,"fix":"split the definition into a smaller metric tree before proposal"}';end if;
 if(a->>'result_scale')::numeric<>trunc((a->>'result_scale')::numeric)or(a->>'result_scale')::numeric not between -32768 and 32767 then raise exception 'result scale must be a structural integer'using errcode='CLR10',detail='{"reason":"structural_integer_invalid","fix":"use an integer JSON number for result_scale within the stored smallint shape"}';end if;
 if not exists(select 1 from clara.metric_units where unit_key=case a->>'unit'when'currency'then'money'else a->>'unit'end)then raise exception 'metric unit is not registered'using errcode='CLR10',detail='{"reason":"declaration_mismatch","fix":"use a registered metric unit"}';end if;if not exists(select 1 from clara.metric_temporalities where temporality_key=a->>'temporality')then raise exception 'metric temporality is not registered'using errcode='CLR10',detail='{"reason":"declaration_mismatch","fix":"use a registered metric temporality"}';end if;if not exists(select 1 from clara.edge_policy_sets where policy_set_key=a->>'edge_policy_set'and firm_id is null)then raise exception 'edge policy identity is not registered'using errcode='CLR10',detail='{"reason":"scope_mismatch","fix":"use a registered product edge-policy set"}';end if;
 todo:=array[a->'root'];levels:=array[1];while i<=coalesce(array_length(todo,1),0)loop n:=todo[i];depth:=levels[i];i:=i+1;if depth>24 then raise exception 'metric AST exceeds proposal depth safety ceiling'using errcode='CLR10',detail='{"reason":"structural_safety_ceiling","class":"depth","limit":24,"fix":"reduce metric nesting below the proposal safety depth of 24 levels"}';end if;if n is null or jsonb_typeof(n)<>'object'or not(n?'node')or jsonb_typeof(n->'node')<>'string'or nullif(n->>'node','')is null then raise exception 'metric node malformed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use a registered node object with a nonblank node tag"}';end if;k:=n->>'node';if k='literal'or n?'value'then raise exception 'numeric literal forbidden'using errcode='CLR10',detail='{"reason":"numeric_literal_forbidden","fix":"use an approved versioned constant"}';end if;
  if k='measure'then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','set','aspect','present_as','scope']))or not(n?'set')or jsonb_typeof(n->'set')<>'object'or exists(select 1 from jsonb_object_keys(n->'set')q where q<>all(array['key','kind']))or not(n->'set'?'key')or jsonb_typeof(n#>'{set,key}')<>'string'or nullif(n#>>'{set,key}','')is null or not(n->'set'?'kind')or jsonb_typeof(n#>'{set,kind}')<>'string'or n#>>'{set,kind}'<>'account_set'or not(n?'aspect')or jsonb_typeof(n->'aspect')<>'string'or nullif(n->>'aspect','')is null or(n?'present_as'and(jsonb_typeof(n->'present_as')<>'string'or nullif(n->>'present_as','')is null))or not(n?'scope')or jsonb_typeof(n->'scope')<>'object'or exists(select 1 from jsonb_object_keys(n->'scope')q where q<>all(array['period','entity','basis']))or not(n->'scope'?'period')or jsonb_typeof(n#>'{scope,period}')<>'string'or nullif(n#>>'{scope,period}','')is null or not(n->'scope'?'entity')or jsonb_typeof(n#>'{scope,entity}')<>'string'or nullif(n#>>'{scope,entity}','')is null or not(n->'scope'?'basis')or jsonb_typeof(n#>'{scope,basis}')<>'string'or nullif(n#>>'{scope,basis}','')is null then raise exception 'measure schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use the closed measure, account-set and scope shapes with registered JSON value types"}';end if;
  elsif k='constant'then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','key']))or not(n?'key')or jsonb_typeof(n->'key')<>'string'or nullif(n->>'key','')is null then raise exception 'constant schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use only node and a nonblank string key"}';end if;
  elsif k='days_in_period'then if exists(select 1 from jsonb_object_keys(n)q where q<>'node')then raise exception 'days schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use only the days_in_period node tag"}';end if;
  elsif k='count'then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','source','scope','domain','item_kind','operation_kind']))or not(n?'source')or jsonb_typeof(n->'source')<>'string'or nullif(n->>'source','')is null or not(n?'scope')or jsonb_typeof(n->'scope')<>'object'or exists(select 1 from jsonb_object_keys(n->'scope')q where q<>all(array['period','entity','basis']))or not(n->'scope'?'period')or jsonb_typeof(n#>'{scope,period}')<>'string'or nullif(n#>>'{scope,period}','')is null or not(n->'scope'?'entity')or jsonb_typeof(n#>'{scope,entity}')<>'string'or nullif(n#>>'{scope,entity}','')is null or not(n->'scope'?'basis')or jsonb_typeof(n#>'{scope,basis}')<>'string'or nullif(n#>>'{scope,basis}','')is null or(n?'domain'and(jsonb_typeof(n->'domain')<>'string'or nullif(n->>'domain','')is null))or(n?'item_kind'and(jsonb_typeof(n->'item_kind')<>'string'or nullif(n->>'item_kind','')is null))or(n?'operation_kind'and(jsonb_typeof(n->'operation_kind')<>'string'or nullif(n->>'operation_kind','')is null))then raise exception 'count schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use the closed count source, scope and optional-filter JSON shapes"}';end if;
  elsif k='lag'then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','periods','of']))or not(n?'periods')or jsonb_typeof(n->'periods')<>'number'or not(n?'of')or jsonb_typeof(n->'of')<>'object'then raise exception 'lag schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use node, integer periods and an object operand"}';end if;if(n->>'periods')::numeric<>trunc((n->>'periods')::numeric)or(n->>'periods')::numeric not between 1 and 2147483647 then raise exception 'lag periods must be a positive structural integer'using errcode='CLR10',detail='{"reason":"structural_integer_invalid","fix":"use an integer JSON number for lag.periods"}';end if;todo:=array_append(todo,n->'of');levels:=array_append(levels,depth+1);
  elsif k in('sum','average')and n?'terms'then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','terms']))or jsonb_typeof(n->'terms')<>'array'or jsonb_array_length(n->'terms')<1 then raise exception 'aggregate schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use only node and a non-empty terms array of node objects"}';end if;for x in select value from jsonb_array_elements(n->'terms')loop if jsonb_typeof(x)<>'object'then raise exception 'aggregate operand malformed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"make every aggregate term a registered node object"}';end if;todo:=array_append(todo,x);levels:=array_append(levels,depth+1);end loop;
  elsif k='average'then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','of']))or not(n?'of')or jsonb_typeof(n->'of')<>'object'then raise exception 'average schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use only node and an object operand"}';end if;todo:=array_append(todo,n->'of');levels:=array_append(levels,depth+1);
  elsif k in('divide','subtract','multiply','percent_change')then if k='divide'then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','num','den']))or not(n?'num')or jsonb_typeof(n->'num')<>'object'or not(n?'den')or jsonb_typeof(n->'den')<>'object'then raise exception 'divide schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"supply object operands num and den only"}';end if;todo:=array_append(array_append(todo,n->'num'),n->'den');levels:=array_append(array_append(levels,depth+1),depth+1);elsif k='percent_change'then if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','current','prior']))or not(n?'current')or jsonb_typeof(n->'current')<>'object'or not(n?'prior')or jsonb_typeof(n->'prior')<>'object'then raise exception 'percent-change schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"supply object operands current and prior only"}';end if;todo:=array_append(array_append(todo,n->'current'),n->'prior');levels:=array_append(array_append(levels,depth+1),depth+1);else if exists(select 1 from jsonb_object_keys(n)q where q<>all(array['node','left','right']))or not(n?'left')or jsonb_typeof(n->'left')<>'object'or not(n?'right')or jsonb_typeof(n->'right')<>'object'then raise exception 'binary schema closed'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"supply object operands left and right only"}';end if;todo:=array_append(array_append(todo,n->'left'),n->'right');levels:=array_append(array_append(levels,depth+1),depth+1);end if;
  else raise exception 'metric primitive unknown'using errcode='CLR10',detail='{"reason":"unknown_field","fix":"use a registered closed primitive"}';end if;
 end loop;return jsonb_build_object('unit',case a->>'unit'when'currency'then'money'else a->>'unit'end,'temp',a->>'temporality','result_scale',a->'result_scale');exception when sqlstate'CLR10'then raise;when others then raise exception 'metric AST structural validation failed'using errcode='CLR10',detail=jsonb_build_object('reason','unknown_field','fix','correct the malformed registered JSON shape','cause',sqlerrm)::text;end$$;
