-- Canonical formula identity normalizes recursive nodes and commutative operands.
create function clara._normalize_metric_node_v1(n jsonb)returns jsonb language plpgsql immutable security definer set search_path=clara,pg_temp as $$declare k text:=n->>'node';a jsonb;b jsonb;t jsonb;begin if k in('sum','average')and n?'terms'then select jsonb_agg(v order by v::text)into t from(select clara._normalize_metric_node_v1(value)v from jsonb_array_elements(n->'terms'))q;return(n-'terms')||jsonb_build_object('terms',t);elsif k in('lag','average')and n?'of'then return(n-'of')||jsonb_build_object('of',clara._normalize_metric_node_v1(n->'of'));elsif k='divide'then return(n-array['num','den'])||jsonb_build_object('num',clara._normalize_metric_node_v1(n->'num'),'den',clara._normalize_metric_node_v1(n->'den'));elsif k='percent_change'then return(n-array['current','prior'])||jsonb_build_object('current',clara._normalize_metric_node_v1(n->'current'),'prior',clara._normalize_metric_node_v1(n->'prior'));elsif k in('subtract','multiply')then a:=clara._normalize_metric_node_v1(n->'left');b:=clara._normalize_metric_node_v1(n->'right');if k='multiply'and a::text>b::text then t:=a;a:=b;b:=t;end if;return(n-array['left','right'])||jsonb_build_object('left',a,'right',b);else return n;end if;end$$;
revoke all on function clara._normalize_metric_node_v1(jsonb)from public;

create function clara._metric_context_sha256_v1(p_snapshot uuid,p_period_ids uuid[],p_firm uuid,p_client uuid,p_producer uuid,p_evaluator uuid,p_dataset_sha256 bytea,p_books_watermark text)returns bytea language sql immutable security definer set search_path=clara,pg_temp as $$select clara._hash(jsonb_build_object('schema','clara.metric-context/v1','snapshot',p_snapshot,'periods',p_period_ids,'firm',p_firm,'entity',p_client,'basis','accrual','producer',p_producer,'evaluator',p_evaluator,'dataset',encode(p_dataset_sha256,'hex'),'books_watermark',p_books_watermark))$$;
