create function clara._metric_resolved_inputs_sha256_v1(p_context_sha256 bytea,p_period_ids uuid[],p_firm uuid,p_client uuid,p_definition uuid,p_formula_sha256 bytea,p_account_set_versions uuid[],p_constant_versions uuid[],p_edge_policy_set uuid,p_averaging_policy uuid,p_evaluator uuid,p_books_watermark text)returns bytea language sql immutable security definer set search_path=clara,pg_temp as $$select clara._hash(jsonb_build_object('schema','clara.metric-resolved-inputs/v1','context',encode(p_context_sha256,'hex'),'periods',p_period_ids,'entity',p_client,'firm',p_firm,'basis','accrual','definition',p_definition,'formula',encode(p_formula_sha256,'hex'),'account_set_versions',array(select x from unnest(coalesce(p_account_set_versions,'{}'))x order by x),'constant_versions',array(select x from unnest(coalesce(p_constant_versions,'{}'))x order by x),'presentation_map_versions','[]'::jsonb,'edge_policy_set_version',p_edge_policy_set,'averaging_policy_version',p_averaging_policy,'evaluator',p_evaluator,'books_watermark',p_books_watermark))$$;
revoke all on function clara._metric_resolved_inputs_sha256_v1(bytea,uuid[],uuid,uuid,uuid,bytea,uuid[],uuid[],uuid,uuid,uuid,text)from public;

-- Product-curated metric family identities. Concrete firm sets resolve only at evaluation.
do $canonical$ declare e uuid;a uuid;k text;d uuid;ast jsonb;norm jsonb;h bytea;begin select id into strict e from clara.edge_policy_sets where policy_set_key='eps_v1'and firm_id is null;select id into strict a from clara.averaging_policy_versions where policy_key='avg_month_end_v1'and firm_id is null;foreach k in array array['current_ratio','quick_ratio','gross_margin','net_margin','revenue_growth','debtor_days','creditor_days','stock_turnover','gearing','expense_to_revenue']loop insert into clara.metric_definitions(firm_id,definition_key,title)values(null,k,initcap(replace(k,'_',' ')))returning id into d;ast:=case k when'current_ratio'then'{"ast":"clara.metric/v1","unit":"ratio","temporality":"point_in_time","result_scale":4,"edge_policy_set":"eps_v1","root":{"node":"divide","num":{"node":"measure","set":{"key":"current_assets","kind":"account_set"},"aspect":"closing_balance","present_as":"natural","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}},"den":{"node":"measure","set":{"key":"current_liabilities","kind":"account_set"},"aspect":"closing_balance","present_as":"natural","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}}}}'::jsonb when'quick_ratio'then'{"ast":"clara.metric/v1","unit":"ratio","temporality":"point_in_time","result_scale":4,"edge_policy_set":"eps_v1","root":{"node":"divide","num":{"node":"measure","set":{"key":"quick_assets","kind":"account_set"},"aspect":"closing_balance","present_as":"natural","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}},"den":{"node":"measure","set":{"key":"current_liabilities","kind":"account_set"},"aspect":"closing_balance","present_as":"natural","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}}}}'::jsonb when'gross_margin'then'{"ast":"clara.metric/v1","unit":"ratio","temporality":"flow","result_scale":4,"edge_policy_set":"eps_v1","root":{"node":"divide","num":{"node":"subtract","left":{"node":"measure","set":{"key":"revenue","kind":"account_set"},"aspect":"period_movement","present_as":"positive_revenue","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}},"right":{"node":"measure","set":{"key":"cost_of_sales","kind":"account_set"},"aspect":"period_movement","present_as":"positive_expense","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}}},"den":{"node":"measure","set":{"key":"revenue","kind":"account_set"},"aspect":"period_movement","present_as":"positive_revenue","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}}}}'::jsonb when'net_margin'then'{"ast":"clara.metric/v1","unit":"ratio","temporality":"flow","result_scale":4,"edge_policy_set":"eps_v1","root":{"node":"divide","num":{"node":"subtract","left":{"node":"measure","set":{"key":"revenue","kind":"account_set"},"aspect":"period_movement","present_as":"positive_revenue","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}},"right":{"node":"measure","set":{"key":"expenses","kind":"account_set"},"aspect":"period_movement","present_as":"positive_expense","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}}},"den":{"node":"measure","set":{"key":"revenue","kind":"account_set"},"aspect":"period_movement","present_as":"positive_revenue","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}}}}'::jsonb when'revenue_growth'then'{"ast":"clara.metric/v1","unit":"ratio","temporality":"flow","result_scale":4,"edge_policy_set":"eps_v1","root":{"node":"percent_change","current":{"node":"measure","set":{"key":"revenue","kind":"account_set"},"aspect":"period_movement","present_as":"positive_revenue","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}},"prior":{"node":"lag","periods":1,"of":{"node":"measure","set":{"key":"revenue","kind":"account_set"},"aspect":"period_movement","present_as":"positive_revenue","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}}}}}'::jsonb when'debtor_days'then'{"ast":"clara.metric/v1","unit":"days","temporality":"flow","result_scale":2,"edge_policy_set":"eps_v1","root":{"node":"multiply","left":{"node":"divide","num":{"node":"average","of":{"node":"measure","set":{"key":"trade_debtors","kind":"account_set"},"aspect":"closing_balance","present_as":"natural","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}}},"den":{"node":"measure","set":{"key":"revenue","kind":"account_set"},"aspect":"period_movement","present_as":"positive_revenue","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}}},"right":{"node":"days_in_period"}}}'::jsonb when'creditor_days'then'{"ast":"clara.metric/v1","unit":"days","temporality":"flow","result_scale":2,"edge_policy_set":"eps_v1","root":{"node":"multiply","left":{"node":"divide","num":{"node":"average","of":{"node":"measure","set":{"key":"trade_creditors","kind":"account_set"},"aspect":"closing_balance","present_as":"natural","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}}},"den":{"node":"measure","set":{"key":"purchases","kind":"account_set"},"aspect":"period_movement","present_as":"positive_expense","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}}},"right":{"node":"days_in_period"}}}'::jsonb when'stock_turnover'then'{"ast":"clara.metric/v1","unit":"ratio","temporality":"flow","result_scale":4,"edge_policy_set":"eps_v1","root":{"node":"divide","num":{"node":"measure","set":{"key":"cost_of_sales","kind":"account_set"},"aspect":"period_movement","present_as":"positive_expense","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}},"den":{"node":"average","of":{"node":"measure","set":{"key":"inventory","kind":"account_set"},"aspect":"closing_balance","present_as":"natural","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}}}}}'::jsonb when'gearing'then'{"ast":"clara.metric/v1","unit":"ratio","temporality":"point_in_time","result_scale":4,"edge_policy_set":"eps_v1","root":{"node":"divide","num":{"node":"measure","set":{"key":"borrowings","kind":"account_set"},"aspect":"closing_balance","present_as":"natural","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}},"den":{"node":"measure","set":{"key":"equity","kind":"account_set"},"aspect":"closing_balance","present_as":"natural","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}}}}'::jsonb else'{"ast":"clara.metric/v1","unit":"ratio","temporality":"flow","result_scale":4,"edge_policy_set":"eps_v1","root":{"node":"divide","num":{"node":"measure","set":{"key":"expenses","kind":"account_set"},"aspect":"period_movement","present_as":"positive_expense","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}},"den":{"node":"measure","set":{"key":"revenue","kind":"account_set"},"aspect":"period_movement","present_as":"positive_revenue","scope":{"period":"$P0","entity":"$CLIENT","basis":"accrual"}}}}'::jsonb end;perform clara.validate_metric_ast_v1(ast);norm:=(ast-'root')||jsonb_build_object('root',clara._normalize_metric_node_v1(ast->'root'));h:=clara._hash(jsonb_build_object('normalized_ast',norm,'unit',case ast->>'unit'when'currency'then'money'else ast->>'unit'end,'temporality',ast->>'temporality','result_scale',(ast->>'result_scale')::smallint,'edge_policy_set','eps_v1','edge_policy_set_id',e,'averaging_policy','avg_month_end_v1','averaging_policy_id',a,'allow_negative',k='gearing'));insert into clara.metric_definition_versions(definition_id,revision,ast,normalized_ast,formula_sha256,unit_key,temporality_key,result_scale,edge_policy_set_id,averaging_policy_id,allow_negative,state,applies_from,proposal_evidence,approved_at,approval_reason,approved_formula_sha256,approval_evidence)values(d,1,ast,norm,h,case ast->>'unit'when'currency'then'money'else ast->>'unit'end,ast->>'temporality',(ast->>'result_scale')::smallint,e,a,k='gearing','canonical','2020-01-01','{"kind":"migration_seed","version":1}',statement_timestamp(),'product-curated canonical definition',h,'{"kind":"migration_approval","version":1}');end loop;end$canonical$;

-- Audited catalog lifecycle. Formula identity uses catalog keys, never period-resolved UUIDs.
create function clara.propose_metric_definition(p_client uuid,p_key text,p_title text,p_unit text,p_temporality text,p_result_scale smallint,p_ast jsonb,p_allow_negative boolean,p_applies_from date,p_applies_to date,p_op_key text)returns jsonb language plpgsql security definer set search_path=clara,pg_temp as $$<<proposal>>declare c record;f uuid;d uuid;v uuid;e uuid;av uuid;h bytea;z jsonb;norm jsonb;validated jsonb;rev int;policy_count int;avg_count int;unit_key text;begin c:=clara._human_ctx(clara.role_rank('admin'));select firm_id into f from clara.clients where id=p_client and firm_id=c.firm;if f is null then raise exception 'client not found in your firm'using errcode='CLR11';end if;unit_key:=case p_unit when'currency'then'money'else p_unit end;validated:=clara._validate_metric_ast_shape_v1(p_ast);if unit_key is distinct from validated->>'unit'or p_temporality is distinct from validated->>'temp'or p_result_scale is distinct from(validated->>'result_scale')::smallint then raise exception 'stored metric declarations do not match AST declarations'using errcode='CLR10',detail='{"reason":"declaration_mismatch","fix":"make unit, temporality and result_scale parameters exactly match the validated AST declarations"}';elsif not exists(select 1 from clara.metric_units mu where mu.unit_key=proposal.unit_key)then raise exception 'metric unit is not registered'using errcode='CLR10',detail='{"reason":"declaration_mismatch","fix":"use a registered metric unit"}';elsif not exists(select 1 from clara.metric_temporalities where temporality_key=p_temporality)then raise exception 'metric temporality is not registered'using errcode='CLR10',detail='{"reason":"declaration_mismatch","fix":"use a registered metric temporality"}';end if;select min(id::text)::uuid,count(*)into e,policy_count from clara.edge_policy_sets where policy_set_key=p_ast->>'edge_policy_set'and firm_id is null and effective_from<=p_applies_from and((p_applies_to is null and effective_to is null)or(p_applies_to is not null and(effective_to is null or effective_to>=p_applies_to)));select min(id::text)::uuid,count(*)into av,avg_count from clara.averaging_policy_versions where policy_key='avg_month_end_v1'and firm_id is null and implemented and effective_from<=p_applies_from and((p_applies_to is null and effective_to is null)or(p_applies_to is not null and(effective_to is null or effective_to>=p_applies_to)));if policy_count<>1 then raise exception 'metric edge policy binding is absent or ambiguous'using errcode='CLR10',detail='{"reason":"scope_mismatch","fix":"use exactly one registered edge-policy version whose effective window covers applies_from through applies_to"}';elsif avg_count<>1 then raise exception 'metric averaging policy binding is absent or ambiguous'using errcode='CLR10',detail='{"reason":"scope_mismatch","fix":"use exactly one implemented avg_month_end_v1 version whose effective window covers applies_from through applies_to"}';end if;norm:=(p_ast-'root')||jsonb_build_object('root',clara._normalize_metric_node_v1(p_ast->'root'));h:=clara._hash(jsonb_build_object('normalized_ast',norm,'unit',unit_key,'temporality',p_temporality,'result_scale',p_result_scale,'edge_policy_set',p_ast->>'edge_policy_set','edge_policy_set_id',e,'averaging_policy','avg_month_end_v1','averaging_policy_id',av,'allow_negative',coalesce(p_allow_negative,false)));z:=clara._reserve_op(f,'propose_metric_definition',p_op_key,clara._hash(jsonb_build_object('client',p_client,'key',p_key,'normalized_ast',norm,'unit',unit_key,'temporality',p_temporality,'result_scale',p_result_scale,'allow_negative',coalesce(p_allow_negative,false),'applies_from',p_applies_from,'applies_to',p_applies_to)));if z is not null then return z;end if;select id into d from clara.metric_definitions where firm_id=f and definition_key=p_key for update;if d is null then insert into clara.metric_definitions(firm_id,definition_key,title,created_by)values(f,p_key,p_title,c.actor)returning id into d;end if;perform pg_advisory_xact_lock(hashtextextended(d::text,0));select coalesce(max(revision),0)+1 into rev from clara.metric_definition_versions where definition_id=d;insert into clara.metric_definition_versions(firm_id,definition_id,revision,ast,normalized_ast,formula_sha256,unit_key,temporality_key,result_scale,edge_policy_set_id,averaging_policy_id,allow_negative,state,applies_from,applies_to,proposed_by,proposal_evidence,approval_evidence)values(f,d,rev,p_ast,norm,h,unit_key,p_temporality,p_result_scale,e,av,coalesce(p_allow_negative,false),'draft',p_applies_from,p_applies_to,c.actor,jsonb_build_object('kind','human_proposal','version',1,'client_id',p_client),'{"kind":"not_applicable","version":1,"reason":"not_approved"}')returning id into v;perform clara._audit(f,c.actor,null,null,'propose_metric_definition',null,jsonb_build_object('client',p_client,'definition_version_id',v,'op_key',p_op_key));return clara._finish_op(f,'propose_metric_definition',p_op_key,jsonb_build_object('definition_version_id',v,'formula_sha256',encode(h,'hex')));end$$;
revoke all on function clara.propose_metric_definition(uuid,text,text,text,text,smallint,jsonb,boolean,date,date,text)from public;grant execute on function clara.propose_metric_definition(uuid,text,text,text,text,smallint,jsonb,boolean,date,date,text)to clara_authenticated;

create function clara.approve_metric_definition(p_definition_version_id uuid,p_expected_formula_sha256 bytea,p_reason text,p_self_approval_attestation text,p_op_key text)returns jsonb language plpgsql security definer set search_path=clara,pg_temp as $$declare c record;v record;z jsonb;validated jsonb;eligible int;bound_set record;measured_count int;begin c:=clara._human_ctx(clara.role_rank('admin'));perform 1 from clara.firms where id=c.firm for update;select x.* into v from clara.metric_definition_versions x where x.id=p_definition_version_id and x.firm_id=c.firm for update;if not found then raise exception 'definition version not found in your firm'using errcode='CLR11';end if;z:=clara._reserve_op(c.firm,'approve_metric_definition',p_op_key,clara._hash(jsonb_build_object('version',v.id,'hash',encode(p_expected_formula_sha256,'hex'),'reason',p_reason,'attestation',p_self_approval_attestation)));if z is not null then return z;end if;if v.state<>'draft'or v.formula_sha256 is distinct from p_expected_formula_sha256 then raise exception 'definition revision/hash mismatch'using errcode='CLR10',detail='{"reason":"formula_hash_mismatch"}';end if;validated:=clara.validate_metric_ast_v1(v.ast);if not exists(select 1 from clara.edge_policy_sets e where e.id=v.edge_policy_set_id and e.policy_set_key=v.ast->>'edge_policy_set'and e.firm_id is null and e.effective_from<=v.applies_from and((v.applies_to is null and e.effective_to is null)or(v.applies_to is not null and(e.effective_to is null or e.effective_to>=v.applies_to))))then raise exception 'edge policy is not effective for the definition'using errcode='CLR10',detail='{"reason":"scope_mismatch","fix":"bind the exact registered edge-policy identity whose effective window covers applies_from through applies_to"}';end if;if not exists(select 1 from clara.averaging_policy_versions a where a.id=v.averaging_policy_id and a.policy_key='avg_month_end_v1'and a.firm_id is null and a.implemented and a.effective_from<=v.applies_from and((v.applies_to is null and a.effective_to is null)or(v.applies_to is not null and(a.effective_to is null or a.effective_to>=v.applies_to))))then raise exception 'averaging policy is not effective for the definition'using errcode='CLR10',detail='{"reason":"scope_mismatch","fix":"bind the exact implemented avg_month_end_v1 identity whose effective window covers applies_from through applies_to"}';end if;if v.unit_key is distinct from validated->>'unit'or v.temporality_key is distinct from validated->>'temp'or v.result_scale is distinct from(validated->>'result_scale')::smallint then raise exception 'stored metric declarations do not match AST declarations'using errcode='CLR10',detail='{"reason":"declaration_mismatch","fix":"make stored unit, temporality and scale match the validated AST"}';end if;if exists(select 1 from(select distinct n#>>'{set,key}'set_key from jsonb_path_query(v.ast,'$.** ? (@.node == "measure")')n)leaf where(select count(*)from clara.account_sets s join clara.account_set_versions av on av.account_set_id=s.id where s.client_id=(v.proposal_evidence->>'client_id')::uuid and s.firm_id=c.firm and s.set_key=leaf.set_key and av.state in('published','superseded')and av.effective_from<=v.applies_from and((v.applies_to is null and av.effective_to is null)or(v.applies_to is not null and(av.effective_to is null or av.effective_to>=v.applies_to))))<>1)then raise exception 'account set binding is absent or ambiguous for approval'using errcode='CLR10',detail='{"reason":"scope_mismatch","fix":"publish exactly one frozen account-set version whose effective window covers the full metric definition window for every measure leaf"}';end if;for bound_set in select distinct n#>>'{set,key}'set_key,av.id version_id from jsonb_path_query(v.ast,'$.** ? (@.node == "measure")')n join clara.account_sets s on s.client_id=(v.proposal_evidence->>'client_id')::uuid and s.firm_id=c.firm and s.set_key=n#>>'{set,key}'join clara.account_set_versions av on av.account_set_id=s.id and av.state in('published','superseded')and av.effective_from<=v.applies_from and((v.applies_to is null and av.effective_to is null)or(v.applies_to is not null and(av.effective_to is null or av.effective_to>=v.applies_to)))loop perform clara.verify_account_set_version_freeze(bound_set.version_id);select count(*)::int into measured_count from clara.account_set_version_members where account_set_version_id=bound_set.version_id;if measured_count>512 then raise exception 'account set expansion exceeds metric leaf bound'using errcode='CLR10',detail=jsonb_build_object('reason','cost_exceeded','class','account_set_expansion','limit',512,'measured_count',measured_count,'set_key',bound_set.set_key,'version_id',bound_set.version_id,'fix','narrow the account-set selector and mint a new version with at most 512 frozen members')::text;end if;end loop;select count(*) into eligible from clara.firm_memberships m join clara.users u on u.id=m.user_id where m.firm_id=c.firm and m.status='active'and m.role in('admin','owner')and not u.is_agent;if eligible=0 then raise exception 'metric definition has no eligible human approver'using errcode='CLR05',detail='{"reason":"no_eligible_human"}';elsif eligible>=2 and v.proposed_by=c.actor then raise exception 'metric definition needs a distinct approver'using errcode='CLR05',detail='{"reason":"distinct_checker"}';elsif eligible=1 and(v.proposed_by<>c.actor or nullif(btrim(p_self_approval_attestation),'')is null)then raise exception 'the sole eligible human may approve only their own proposal with attestation'using errcode='CLR05',detail=case when v.proposed_by<>c.actor then'{"reason":"sole_eligible_proposer_mismatch"}'else'{"reason":"self_approval_attestation_missing"}'end;end if;update clara.metric_definition_versions set state='firm_approved',approved_by=c.actor,approved_at=statement_timestamp(),approval_reason=p_reason,self_approval_attestation=case when eligible=1 then p_self_approval_attestation end,approved_formula_sha256=formula_sha256,approval_evidence=jsonb_build_object('kind','human_approval','version',1,'reason',p_reason,'eligible_human_count',eligible,'self_approved',v.proposed_by=c.actor)where id=v.id;perform clara._audit(c.firm,c.actor,null,null,'approve_metric_definition',null,jsonb_build_object('definition_version_id',v.id,'op_key',p_op_key));return clara._finish_op(c.firm,'approve_metric_definition',p_op_key,jsonb_build_object('definition_version_id',v.id,'state','firm_approved'));end$$;
revoke all on function clara.approve_metric_definition(uuid,bytea,text,text,text)from public;grant execute on function clara.approve_metric_definition(uuid,bytea,text,text,text)to clara_authenticated;

create function clara.reject_metric_definition(p_definition_version_id uuid,p_reason text,p_op_key text)returns jsonb language plpgsql security definer set search_path=clara,pg_temp as $$declare c record;v record;z jsonb;begin c:=clara._human_ctx(clara.role_rank('owner'));select * into v from clara.metric_definition_versions where id=p_definition_version_id and firm_id=c.firm for update;if not found then raise exception 'definition version not found in your firm'using errcode='CLR11';end if;z:=clara._reserve_op(c.firm,'reject_metric_definition',p_op_key,clara._hash(jsonb_build_object('version',v.id,'reason',p_reason)));if z is not null then return z;end if;if v.state<>'draft'then raise exception 'only a draft may be rejected'using errcode='CLR10';end if;update clara.metric_definition_versions set state='rejected',approval_reason=p_reason where id=v.id;perform clara._audit(c.firm,c.actor,null,null,'reject_metric_definition',null,jsonb_build_object('definition_version_id',v.id,'op_key',p_op_key));return clara._finish_op(c.firm,'reject_metric_definition',p_op_key,jsonb_build_object('definition_version_id',v.id,'state','rejected'));end$$;
revoke all on function clara.reject_metric_definition(uuid,text,text)from public;grant execute on function clara.reject_metric_definition(uuid,text,text)to clara_authenticated;

create function clara.supersede_metric_definition(p_definition_version_id uuid,p_successor_version_id uuid,p_reason text,p_op_key text)returns jsonb language plpgsql security definer set search_path=clara,pg_temp as $$declare c record;v record;s record;z jsonb;begin c:=clara._human_ctx(clara.role_rank('owner'));if p_definition_version_id=p_successor_version_id then raise exception 'supersession must point strictly forward'using errcode='CLR10',detail='{"reason":"supersession_direction"}';end if;perform 1 from clara.metric_definition_versions where id in(p_definition_version_id,p_successor_version_id)and firm_id=c.firm order by id for update;if(select count(*)from clara.metric_definition_versions where id in(p_definition_version_id,p_successor_version_id)and firm_id=c.firm)<>2 then raise exception 'supersession binding invalid'using errcode='CLR10';end if;select * into strict v from clara.metric_definition_versions where id=p_definition_version_id and firm_id=c.firm;select * into strict s from clara.metric_definition_versions where id=p_successor_version_id and firm_id=c.firm;if v.definition_id<>s.definition_id or v.state not in('firm_approved','canonical')or s.state<>'firm_approved'or s.revision<=v.revision or s.supersedes_version_id is not null then raise exception 'supersession must bind a higher approved revision in the same firm and lineage'using errcode='CLR10',detail='{"reason":"supersession_direction"}';end if;z:=clara._reserve_op(c.firm,'supersede_metric_definition',p_op_key,clara._hash(jsonb_build_object('version',v.id,'successor',s.id,'reason',p_reason)));if z is not null then return z;end if;update clara.metric_definition_versions set state='superseded',approval_reason=p_reason where id=v.id;update clara.metric_definition_versions set supersedes_version_id=v.id where id=s.id;perform clara._audit(c.firm,c.actor,null,null,'supersede_metric_definition',null,jsonb_build_object('definition_version_id',v.id,'successor_version_id',s.id,'op_key',p_op_key));return clara._finish_op(c.firm,'supersede_metric_definition',p_op_key,jsonb_build_object('definition_version_id',v.id,'state','superseded'));end$$;
revoke all on function clara.supersede_metric_definition(uuid,uuid,text,text)from public;grant execute on function clara.supersede_metric_definition(uuid,uuid,text,text)to clara_authenticated;

-- Primary recursion: all successful values are reduced exact numerator/positive-denominator pairs.
create function clara._metric_eval_node_v1(p_client uuid,p_snapshot uuid,p_context uuid,p_period uuid,n jsonb,p_allow_negative boolean,p_average_key text,p_as_of date default null)returns clara.metric_value_v1 language plpgsql stable security definer set search_path=clara,pg_temp as $$
declare r clara.metric_value_v1;a clara.metric_value_v1;b clara.metric_value_v1;k text:=n->>'node';x jsonb;rp record;av record;cv record;av_id uuid;match_count int;live_ids uuid[];frozen_ids uuid[];actual_count int;bad_count int;target uuid:=p_period;shifts int:=0;i int;rows_n int;terms_n int:=0;g numeric;h numeric;t numeric;sample_on date;sample_n int:=0;amount numeric;present text;source text;signs jsonb:='[]';operand_values jsonb:='[]';
begin r.status:='ok';r.denominator:=1;r.account_set_version_ids:='{}';r.constant_version_ids:='{}';r.entry_ids:='{}';r.document_ids:='{}';r.inputs:='{}';if k in('measure','count')then shifts:=case when n#>>'{scope,period}'='$P0'then 0 else substring(n#>>'{scope,period}'from 4)::int end;elsif k='lag'then shifts:=(n->>'periods')::int;end if;if shifts>0 then for i in 1..shifts loop select p.* into rp from clara.metric_input_snapshot_periods sp join clara.reporting_periods p on p.id=sp.period_id and p.firm_id=sp.firm_id and p.client_id=sp.client_id where sp.snapshot_id=p_snapshot and sp.period_id=target and sp.client_id=p_client;if rp.id is null then target:=null;exit;elsif rp.grain='month'then select sp.period_id into target from clara.metric_input_snapshot_periods sp join clara.reporting_periods p on p.id=sp.period_id and p.firm_id=sp.firm_id and p.client_id=sp.client_id where sp.snapshot_id=p_snapshot and sp.client_id=p_client and p.grain='month'and sp.period_start=(rp.period_start-interval'1 month')::date;elsif rp.grain='fiscal_year'then select sp.period_id into target from clara.metric_input_snapshot_periods sp join clara.reporting_periods p on p.id=sp.period_id and p.firm_id=sp.firm_id and p.client_id=sp.client_id where sp.snapshot_id=p_snapshot and sp.client_id=p_client and p.grain='fiscal_year'and sp.period_end=rp.period_start-1;else target:=null;end if;if target is null or not exists(select 1 from clara.metric_evaluation_context_periods where context_id=p_context and period_id=target)then target:=null;exit;end if;end loop;if target is null then r.status:='absent';r.reason_key:='prior_period_absent';return r;end if;end if;select p.* into rp from clara.metric_input_snapshot_periods sp join clara.reporting_periods p on p.id=sp.period_id and p.firm_id=sp.firm_id and p.client_id=sp.client_id where sp.snapshot_id=p_snapshot and sp.period_id=target;if rp.id is null then r.status:='absent';r.reason_key:=case when shifts>0 then'prior_period_absent'else'absent'end;return r;end if;r.period_id:=target;
 if k='measure'then select min(v.id::text)::uuid,count(*) into av_id,match_count from clara.account_set_versions v join clara.account_sets s on s.id=v.account_set_id where s.firm_id=rp.firm_id and s.client_id=p_client and v.firm_id=rp.firm_id and v.client_id=p_client and s.set_key=n#>>'{set,key}'and v.state in('published','superseded')and v.effective_from<=rp.period_start and(v.effective_to is null or v.effective_to>=rp.period_start);if match_count=0 then r.status:='refused';r.reason_key:='account_set_resolution_absent';r.inputs:=jsonb_build_object('account_set_resolution',jsonb_build_object('set_key',n#>>'{set,key}','candidate_count',0,'period_id',target),'sign_normalizations',jsonb_build_array(coalesce(n->>'present_as','natural')),'input_values',jsonb_build_object('node','measure','period_id',target,'aspect',n->>'aspect','present_as',coalesce(n->>'present_as','natural'),'account_set_resolution',jsonb_build_object('set_key',n#>>'{set,key}','candidate_count',0,'period_id',target),'value',null));return r;elsif match_count>1 then r.status:='refused';r.reason_key:='account_set_resolution_ambiguous';r.inputs:=jsonb_build_object('account_set_resolution',jsonb_build_object('set_key',n#>>'{set,key}','candidate_count',match_count,'period_id',target),'sign_normalizations',jsonb_build_array(coalesce(n->>'present_as','natural')),'input_values',jsonb_build_object('node','measure','period_id',target,'aspect',n->>'aspect','present_as',coalesce(n->>'present_as','natural'),'account_set_resolution',jsonb_build_object('set_key',n#>>'{set,key}','candidate_count',match_count,'period_id',target),'value',null));return r;end if;select * into strict av from clara.account_set_versions where id=av_id;r.account_set_version_ids:=array[av.id];select coalesce(array_agg(m.account_id order by m.ordinal),'{}'),count(*)::int,count(*)filter(where m.ordinal<>m.ro-1 or m.ordinal<>m.ra-1)::int into frozen_ids,actual_count,bad_count from(select vm.account_id,vm.ordinal,row_number()over(order by vm.ordina