create function clara.evaluate_metric_v1(p_client uuid,p_definition_version_id uuid,p_period_ids uuid[],p_snapshot_id uuid,p_run_id uuid)returns jsonb language plpgsql security definer set search_path=clara,pg_temp as $$declare c record;dv record;s record;ctx record;ev uuid;root_period uuid;root_start date;v clara.metric_value_v1;z jsonb;reason_id uuid;cell uuid;factor numeric;q numeric;rem numeric;shown text;na jsonb;bound_period_ids uuid[];begin c:=clara._human_ctx(clara.role_rank('bookkeeper'));if p_period_ids is null or cardinality(p_period_ids)not between 1 and 25 or cardinality(array(select distinct x from unnest(p_period_ids)x))<>cardinality(p_period_ids)then raise exception 'context period binding invalid'using errcode='CLR10',detail='{"reason":"cost_exceeded","class":"context_periods","limit":25}';end if;select * into s from clara.metric_input_snapshots where id=p_snapshot_id and client_id=p_client and firm_id=c.firm;if s.id is null or cardinality(p_period_ids)<>(select count(*)from clara.metric_input_snapshot_periods where snapshot_id=s.id and period_id=any(p_period_ids))then raise exception 'metric snapshot/context binding incomplete'using errcode='CLR11';end if;select * into dv from clara.metric_definition_versions where id=p_definition_version_id and(firm_id is null or firm_id=c.firm)and state in('canonical','firm_approved');if dv.id is null then raise exception 'definition is not approved for this firm'using errcode='CLR11';end if;root_period:=p_period_ids[1];if not exists(select 1 from clara.metric_input_snapshot_periods p where p.snapshot_id=s.id and p.period_id=root_period and dv.applies_from<=p.period_start and(dv.applies_to is null or dv.applies_to>=p.period_start))then raise exception 'definition is not effective for target period'using errcode='CLR10',detail='{"reason":"scope_mismatch"}';end if;select period_start into strict root_start from clara.metric_input_snapshot_periods where snapshot_id=s.id and period_id=root_period;perform clara.validate_metric_ast_v1(dv.ast);select id into ev from clara.evaluator_versions where evaluator_name='evaluate_metric'and version=1 and firm_id is null and deployed;if ev is null then raise exception 'metric evaluator is not deployed'using errcode='CLR10',detail='{"reason":"evaluator_undeployed"}';end if;perform pg_advisory_xact_lock(hashtextextended(c.firm::text||':'||p_run_id::text,0));z:=clara._reserve_op(c.firm,'evaluate_metric_v1',p_run_id::text||':'||dv.id::text,clara._hash(jsonb_build_object('client',p_client,'definition',dv.id,'periods',p_period_ids,'snapshot',s.id)));if z is not null then return z;end if;if(select count(*)from clara.metric_cells where firm_id=c.firm and run_id=p_run_id)>=5000 then raise exception 'metric run cost exceeded'using errcode='CLR10',detail='{"reason":"cost_exceeded","class":"cells_per_run","limit":5000}';end if;select * into ctx from clara.metric_evaluation_contexts where client_id=p_client and run_id=p_run_id for update;if ctx.id is null then if exists(select 1 from clara.metric_evaluation_contexts where firm_id=c.firm and run_id=p_run_id)then raise exception 'run context is ambiguous within the firm'using errcode='CLR10',detail='{"reason":"scope_mismatch","class":"run_context"}';end if;insert into clara.metric_evaluation_contexts(firm_id,client_id,snapshot_id,evaluator_version_id,run_id,context_sha256,created_by)values(c.firm,p_client,s.id,ev,p_run_id,clara._metric_context_sha256_v1(s.id,p_period_ids,c.firm,p_client,s.producer_version_id,ev,s.dataset_sha256,s.books_watermark),c.actor)returning * into ctx;insert into clara.metric_evaluation_context_periods select ctx.id,s.id,c.firm,p_client,p.period_id,p.period_start,p.period_end,u.ord-1 from unnest(p_period_ids)with ordinality u(pid,ord)join clara.metric_input_snapshot_periods p on p.snapshot_id=s.id and p.period_id=u.pid;else select array_agg(period_id order by ordinal)into bound_period_ids from clara.metric_evaluation_context_periods where context_id=ctx.id;if ctx.snapshot_id<>s.id or ctx.evaluator_version_id<>ev or bound_period_ids is distinct from p_period_ids then raise exception 'run context is immutable and mismatched'using errcode='CLR10',detail='{"reason":"scope_mismatch"}';end if;end if;v:=clara._metric_eval_node_v1(p_client,s.id,ctx.id,root_period,dv.ast->'root',dv.allow_negative,(select policy_key from clara.averaging_policy_versions where id=dv.averaging_policy_id),null);if v.status<>'ok'then select id into reason_id from clara.metric_na_reason_versions where reason_key=v.reason_key and firm_id is null and effective_from<=root_start and(effective_to is null or effective_to>=root_start)order by version desc limit 1;if reason_id is null then raise exception 'no N/A reason version is effective for the root reporting period'using errcode='CLR10',detail=jsonb_build_object('reason','scope_mismatch','class','na_reason_effectivity','reason_key',v.reason_key,'root_period_start',root_start,'fix','publish one metric_na_reason_versions row whose effective window covers the root reporting period start')::text;end if;else factor:=power(10::numeric,dv.result_scale);q:=div(abs(v.numerator)*factor,v.denominator);rem:=mod(abs(v.numerator)*factor,v.denominator);if rem*2>=v.denominator then q:=q+1;end if;shown:=to_char((case when v.numerator<0 then-q else q end)/factor,'FM999999999999999999999999999999999999999999999999990'||case when dv.result_scale>0 then'.'||repeat('0',dv.result_scale)else''end);end if;na:=jsonb_build_object('presentation_map_versions',jsonb_build_object('version',1,'reason','definition_has_no_presentation_map_binding'),'model_proposal',jsonb_build_object('version',1,'reason','evaluator_originated'),'human_approval',jsonb_build_object('version',1,'reason','no_numeric_approval'),'supersession',jsonb_build_object('version',1,'reason','first_mint'));if cardinality(v.document_ids)=0 then na:=na||jsonb_build_object('documents',jsonb_build_object('version',1,'reason','no_document-backed_input_rows'));end if;insert into clara.metric_cells(firm_id,client_id,run_id,evaluation_context_id,definition_version_id,formula_sha256,resolved_inputs_sha256,evaluator_version_id,books_watermark,cell_status,na_reason_version_id,exact_numerator,exact_denominator,unit_key,displayed_scale,displayed_text,inputs)values(c.firm,p_client,p_run_id,ctx.id,dv.id,dv.formula_sha256,clara._metric_resolved_inputs_sha256_v1(ctx.context_sha256,p_period_ids,c.firm,p_client,dv.id,dv.formula_sha256,v.account_set_version_ids,v.constant_version_ids,dv.edge_policy_set_id,dv.averaging_policy_id,ev,s.books_watermark),ev,s.books_watermark,v.status,reason_id,case when v.status='ok'then v.numerator end,case when v.status='ok'then v.denominator end,dv.unit_key,case when v.status='ok'then dv.result_scale end,shown,coalesce(v.inputs,'{}')||jsonb_build_object('normalized_provenance',jsonb_build_object('period_ids',p_period_ids,'snapshot_ids',array[s.id],'account_set_version_ids',array(select x from unnest(v.account_set_version_ids)x order by x),'constant_version_ids',array(select x from unnest(v.constant_version_ids)x order by x),'entry_ids',array(select x from unnest(v.entry_ids)x order by x),'document_ids',array(select x from unnest(v.document_ids)x order by x),'presentation_map_version_ids','{}'::uuid[]),'schema','clara.metric-cell-inputs/v1','provenance_not_applicable',na))returning id into cell;insert into clara.metric_cell_periods select cell,c.firm,p_client,p.period_id,p.period_start,p.period_end,u.ord-1 from unnest(p_period_ids)with ordinality u(pid,ord)join clara.metric_input_snapshot_periods p on p.snapshot_id=s.id and p.period_id=u.pid;insert into clara.metric_cell_snapshots values(cell,c.firm,p_client,s.id);insert into clara.metric_cell_account_sets select cell,c.firm,p_client,x from unnest(v.account_set_version_ids)x;insert into clara.metric_cell_constants select cell,c.firm,p_client,x from unnest(v.constant_version_ids)x;insert into clara.metric_cell_entries select cell,c.firm,p_client,x from unnest(v.entry_ids)x;insert into clara.metric_cell_documents select cell,c.firm,p_client,x from unnest(v.document_ids)x;perform clara._audit(c.firm,c.actor,null,null,'evaluate_metric_v1',null,jsonb_build_object('client',p_client,'cell_id',cell,'run_id',p_run_id));return clara._finish_op(c.firm,'evaluate_metric_v1',p_run_id::text||':'||dv.id::text,jsonb_build_object('cell_id',cell,'cell_status',v.status,'reason_key',v.reason_key));end$$;
revoke all on function clara.evaluate_metric_v1(uuid,uuid,uuid[],uuid,uuid)from public;grant execute on function clara.evaluate_metric_v1(uuid,uuid,uuid[],uuid,uuid)to clara_authenticated;

-- Pack orchestration is deliberately thin: it preflights the complete request, then reuses the
-- frozen scalar evaluator in caller-supplied definition order. Any error aborts the caller's
-- statement/transaction, so a timeout or later-definition failure cannot leave partial cells.
create function clara.evaluate_fs_pack_v1(p_client uuid,p_definition_version_ids uuid[],p_period_ids uuid[],p_snapshot_id uuid,p_run_id uuid)returns jsonb language plpgsql security definer set search_path=clara,pg_temp as $pack$
declare c record;s record;ctx record;dv record;item record;cell_row record;ev uuid;ctx_id uuid;root_start date;bound_period_ids uuid[];existing_count int;requested_count int;new_required int;measured_count int;context_count int;cell_receipt jsonb;z jsonb;result jsonb;cells jsonb:='[]'::jsonb;
begin
 c:=clara._human_ctx(clara.role_rank('bookkeeper'));
 if p_client is null or p_snapshot_id is null or p_run_id is null then raise exception 'metric pack scalar identities must be nonnull'using errcode='CLR10',detail='{"reason":"invalid_request","class":"pack_identity","constraint":"nonnull"}';end if;
 if p_definition_version_ids is null or cardinality(p_definition_version_ids)=0 or array_position(p_definition_version_ids,null) is not null then raise exception 'metric pack definitions must be nonempty identities'using errcode='CLR10',detail='{"reason":"invalid_request","class":"definition_versions","constraint":"nonempty_nonnull"}';end if;
 requested_count:=cardinality(p_definition_version_ids);
 if requested_count>5000 then raise exception 'metric pack run cost exceeded'using errcode='CLR10',detail=jsonb_build_object('reason','cost_exceeded','class','cells_per_run','limit',5000,'measured_count',requested_count,'existing_count',0,'requested_count',requested_count)::text;end if;
 if cardinality(array(select distinct x from unnest(p_definition_version_ids)x))<>requested_count then raise exception 'metric pack definitions must be unique'using errcode='CLR10',detail='{"reason":"invalid_request","class":"definition_versions","constraint":"unique"}';end if;
 if p_period_ids is null or cardinality(p_period_ids)=0 or array_position(p_period_ids,null) is not null then raise exception 'metric pack periods must be nonempty identities'using errcode='CLR10',detail='{"reason":"invalid_request","class":"context_periods","constraint":"nonempty_nonnull"}';end if;
 if cardinality(p_period_ids)>25 then raise exception 'metric pack context period cost exceeded'using errcode='CLR10',detail=jsonb_build_object('reason','cost_exceeded','class','context_periods','limit',25,'measured_count',cardinality(p_period_ids))::text;end if;
 if cardinality(array(select distinct x from unnest(p_period_ids)x))<>cardinality(p_period_ids)then raise exception 'metric pack periods must be unique'using errcode='CLR10',detail='{"reason":"invalid_request","class":"context_periods","constraint":"unique"}';end if;
 perform pg_advisory_xact_lock(hashtextextended(c.firm::text||':'||p_run_id::text,0));
 z:=clara._reserve_op(c.firm,'evaluate_fs_pack_v1',p_run_id::text,clara._hash(jsonb_build_object('client',p_client,'definitions',p_definition_version_ids,'periods',p_period_ids,'snapshot',p_snapshot_id)));
 if z is not null then if z?'pending' or jsonb_typeof(z->'cells')is distinct from'array'or jsonb_array_length(z->'cells')<>requested_count then raise exception 'metric pack operation is unfinished or malformed'using errcode='CLR10',detail='{"reason":"operation_pending"}';end if;return z;end if;
 select count(*)::int into existing_count from clara.metric_cells where firm_id=c.firm and run_id=p_run_id;
 select count(*)::int into new_required from unnest(p_definition_version_ids)u(definition_version_id)where not exists(select 1 from clara.metric_cells mc where mc.firm_id=c.firm and mc.client_id=p_client and mc.run_id=p_run_id and mc.definition_version_id=u.definition_version_id);
 measured_count:=existing_count+new_required;
 if measured_count>5000 then raise exception 'metric pack run cost exceeded'using errcode='CLR10',detail=jsonb_build_object('reason','cost_exceeded','class','cells_per_run','limit',5000,'measured_count',measured_count,'existing_count',existing_count,'new_required',new_required,'requested_count',requested_count)::text;end if;
 select * into s from clara.metric_input_snapshots where id=p_snapshot_id and client_id=p_client and firm_id=c.firm;
 if s.id is null or cardinality(p_period_ids)<>(select count(*)from clara.metric_input_snapshot_periods where snapshot_id=s.id and period_id=any(p_period_ids))then raise exception 'metric pack snapshot/context binding incomplete'using errcode='CLR11';end if;
 select period_start into root_start from clara.metric_input_snapshot_periods where snapshot_id=s.id and period_id=p_period_ids[1];
 select id into ev from clara.evaluator_versions where evaluator_name='evaluate_metric'and version=1 and firm_id is null and deployed;
 if ev is null then raise exception 'metric evaluator is not deployed'using errcode='CLR10',detail='{"reason":"evaluator_undeployed"}';end if;
 select count(*)::int,min(ec.id::text)::uuid into context_count,ctx_id from clara.metric_evaluation_contexts ec where ec.firm_id=c.firm and ec.run_id=p_run_id;
 if context_count>1 then raise exception 'run context is ambiguous within the firm'using errcode='CLR10',detail='{"reason":"scope_mismatch","class":"run_context"}';end if;
 if ctx_id is not null then select ec.* into strict ctx from clara.metric_evaluation_contexts ec where ec.id=ctx_id for update;select array_agg(period_id order by ordinal)into bound_period_ids from clara.metric_evaluation_context_periods where context_id=ctx.id;if ctx.client_id<>p_client or ctx.snapshot_id<>s.id or ctx.evaluator_version_id<>ev or bound_period_ids is distinct from p_period_ids then raise exception 'run context is immutable and mismatched'using errcode='CLR10',detail='{"reason":"scope_mismatch","class":"run_context"}';end if;end if;
 for item in select u.definition_version_id,u.ordinality from unnest(p_definition_version_ids)with ordinality u(definition_version_id,ordinality)order by u.ordinality loop
  select v.* into dv from clara.metric_definition_versions v join clara.metric_definitions d on d.id=v.definition_id and d.firm_id is not distinct from v.firm_id where v.id=item.definition_version_id and(v.firm_id is null or v.firm_id=c.firm)and v.state in('canonical','firm_approved')and v.approved_formula_sha256=v.formula_sha256;
  if dv.id is null then raise exception 'pack definition is not approved for this firm'using errcode='CLR11',detail=jsonb_build_object('reason','definition_unavailable','definition_version_id',item.definition_version_id,'ordinal',item.ordinality-1)::text;end if;
  if dv.applies_from>root_start or(dv.applies_to is not null and dv.applies_to<root_start)then raise exception 'pack definition is not effective for target period'using errcode='CLR10',detail=jsonb_build_object('reason','scope_mismatch','class','definition_effectivity','definition_version_id',dv.id,'ordinal',item.ordinality-1)::text;end if;
  perform clara.validate_metric_ast_v1(dv.ast);
 end loop;
 for item in select u.definition_version_id,u.ordinality from unnest(p_definition_version_ids)with ordinality u(definition_version_id,ordinality)order by u.ordinality loop
  cell_receipt:=clara.evaluate_metric_v1(p_client,item.definition_version_id,p_period_ids,p_snapshot_id,p_run_id);
  if cell_receipt?'pending' or jsonb_typeof(cell_receipt)<>'object' or not(cell_receipt?'cell_id') or not(cell_receipt?'cell_status')then raise exception 'metric pack encountered an unfinished or malformed scalar operation'using errcode='CLR10',detail=jsonb_build_object('reason','operation_pending','definition_version_id',item.definition_version_id,'ordinal',item.ordinality-1)::text;end if;
  select mc.id,mc.cell_status,nr.reason_key into cell_row from clara.metric_cells mc left join clara.metric_na_reason_versions nr on nr.id=mc.na_reason_version_id where mc.id=(cell_receipt->>'cell_id')::uuid and mc.firm_id=c.firm and mc.client_id=p_client and mc.run_id=p_run_id and mc.definition_version_id=item.definition_version_id and mc.evaluator_version_id=ev and mc.evaluation_context_id=(select id from clara.metric_evaluation_contexts where client_id=p_client and run_id=p_run_id)and mc.cell_status=cell_receipt->>'cell_status'and nr.reason_key is not distinct from cell_receipt->>'reason_key';
  if cell_row.id is null then raise exception 'metric pack scalar receipt does not identify its exact durable cell'using errcode='CLR10',detail=jsonb_build_object('reason','cell_identity_mismatch','definition_version_id',item.definition_version_id,'ordinal',item.ordinality-1)::text;end if;
  cells:=cells||jsonb_build_array(jsonb_build_object('ordinal',item.ordinality-1,'definition_version_id',item.definition_version_id,'cell_id',cell_row.id,'cell_status',cell_row.cell_status,'reason_key',cell_row.reason_key));
 end loop;
 result:=jsonb_build_object('client_id',p_client,'run_id',p_run_id,'snapshot_id',p_snapshot_id,'definition_version_ids',p_definition_version_ids,'period_ids',p_period_ids,'cell_count',requested_count,'cells',cells);
 perform clara._audit(c.firm,c.actor,null,null,'evaluate_fs_pack_v1',null,jsonb_build_object('client',p_client,'run_id',p_run_id,'definition_version_ids',p_definition_version_ids,'cell_count',requested_count));
 return clara._finish_op(c.firm,'evaluate_fs_pack_v1',p_run_id::text,result);
end$pack$;
revoke all on function clara.evaluate_fs_pack_v1(uuid,uuid[],uuid[],uuid,uuid)from public;grant execute on function clara.evaluate_fs_pack_v1(uuid,uuid[],uuid[],uuid,uuid)to clara_authenticated;

-- Independent E6 recursion deliberately duplicates calendar, selector, rational and edge logic.
-- It calls no primary evaluator/validator/helper and reads all four immutable fact families.
create function clara._metric_recheck_node_v1(p_client uuid,p_snapshot uuid,p_context uuid,p_period uuid,n jsonb,p_allow_negative boolean,p_average_key text,p_as_of date default null)returns clara.metric_value_v1 language plpgsql stable security definer set search_path=clara,pg_temp as $$
declare r clara.metric_value_v1;a clara.metric_value_v1;b clara.metric_value_v1;k text:=n->>'node';x jsonb;rp record;av record;cv record;av_id uuid;match_count int;live_ids uuid[];frozen_ids uuid[];allowed text[]:=array['account_ids','account_codes','account_types','account_classes','code_from','code_to'];unresolved jsonb;actual_count int;bad_count int;target uuid:=p_period;shifts int:=0;i int;rows_n int;terms_n int:=0;g numeric;h numeric;t numeric;sample_on date;sample_n int:=0;amount numeric;present text;source text;signs jsonb:='[]';operand_values jsonb:='[]';
begin if n is null or jsonb_typeof(n)<>'object'or not(n?'node')or jsonb_typeof(n->'node')<>'string'or k is null or k<>all(array['measure','constant','days_in_period','count','lag','sum','average','divide','subtract','multiply','percent_change'])then raise exception 'independent metric recheck reached a malformed or unregistered node'using errcode='CLR10',detail=jsonb_build_object('reason','unknown_field','class','independent_recheck_node','node',coalesce(k,'(absent)'),'fix','hand the independent evaluator a registered closed metric node object')::text;end if;r.status:='ok';r.denominator:=1;r.account_set_version_ids:='{}';r.constant_version_ids:='{}';r.entry_ids:='{}';r.document_ids:='{}';r.inputs:='{}';if k in('measure','count')then shifts:=case when n#>>'{scope,period}'='$P0'then 0 else substring(n#>>'{scope,period}'from 4)::int end;elsif k='lag'then shifts:=(n->>'periods')::int;end if;if shifts>0 then for i in 1..shifts loop select p.* into rp from clara.metric_input_snapshot_periods sp join clara.reporting_periods p on p.id=sp.period_id and p.firm_id=sp.firm_id and p.client_id=sp.client_id where sp.snapshot_id=p_snapshot and sp.period_id=target and sp.client_id=p_client;if rp.id is null then target:=null;exit;elsif rp.grain='month'then select sp.period_id into target from clara.metric_input_snapshot_periods sp join clara.reporting_periods p on p.id=sp.period_id and p.firm_id=sp.firm_id and p.client_id=sp.client_id where sp.snapshot_id=p_snapshot and sp.client_id=p_client and p.grain='month'and sp.period_start=(rp.period_start-interval'1 month')::date;elsif rp.grain='fiscal_year'then select sp.period_id into target from clara.metric_input_snapshot_periods sp join clara.reporting_periods p on p.id=sp.period_id and p.firm_id=sp.firm_id and p.client_id=sp.client_id where sp.snapshot_id=p_snapshot and sp.client_id=p_client and p.grain='fiscal_year'and sp.period_end=rp.period_start-1;else target:=null;end if;if target is null or not exists(select 1 from clara.metric_ev