create function clara.assess_metric_cell_independent_v1(p_cell_id uuid,p_expected_cell_id uuid,p_op_key text)returns jsonb language plpgsql security definer set search_path=clara,pg_temp as $$declare c record;mc record;expected record;dv record;ctx record;expected_reason text;root_period uuid;comp jsonb;root_ast jsonb;scale smallint;allow_neg boolean;avg_key text;v clara.metric_value_v1;z jsonb;aid uuid;ev uuid;same boolean;factor numeric;q numeric;rem numeric;shown text;expected_account_sets uuid[];expected_constants uuid[];expected_entries uuid[];expected_documents uuid[];expected_evaluator_inputs jsonb;expected_signs jsonb;begin c:=clara._human_ctx(clara.role_rank('bookkeeper'));select * into mc from clara.metric_cells where id=p_cell_id and firm_id=c.firm;if mc.id is null then raise exception 'metric cell not found in your firm'using errcode='CLR11';end if;select * into expected from clara.metric_cells where id=p_expected_cell_id and firm_id=c.firm and client_id=mc.client_id;if expected.id is null then raise exception 'expected metric cell not found in your firm'using errcode='CLR11';end if;z:=clara._reserve_op(c.firm,'assess_metric_cell_independent_v1',p_op_key,sha256(convert_to(jsonb_build_object('cell',p_cell_id,'expected',p_expected_cell_id)::text,'UTF8')));if z is not null then return z;end if;select * into strict ctx from clara.metric_evaluation_contexts where id=mc.evaluation_context_id;if mc.definition_version_id is null then comp:=mc.inputs->'composition';if mc.inputs->>'schema' is distinct from'clara.metric-composition-inputs/v1'or jsonb_typeof(comp)is distinct from'object'or comp->>'evaluator_entrypoint'is distinct from(select e.entrypoint_signature from clara.evaluator_versions e where e.id=ctx.evaluator_version_id)or jsonb_typeof(comp->'ast')is distinct from'object'or jsonb_typeof(comp#>'{ast,root}')is distinct from'object'or jsonb_typeof(comp#>'{ast,result_scale}')is distinct from'number'or sha256(convert_to(comp::text,'UTF8'))is distinct from mc.formula_sha256 then raise exception 'definitionless metric cell has no hash-bound typed composition to replay independently'using errcode='CLR11',detail='{"reason":"composition_schema_absent"}';end if;root_ast:=comp#>'{ast,root}';scale:=(comp#>>'{ast,result_scale}')::smallint;allow_neg:=coalesce((comp->>'allow_negative')::boolean,false);avg_key:=coalesce(comp->>'averaging_policy','avg_month_end_v1');else select * into strict dv from clara.metric_definition_versions where id=mc.definition_version_id;root_ast:=dv.ast->'root';scale:=dv.result_scale;allow_neg:=dv.allow_negative;select policy_key into strict avg_key from clara.averaging_policy_versions where id=dv.averaging_policy_id;end if;select period_id into strict root_period from clara.metric_evaluation_context_periods where context_id=ctx.id order by ordinal limit 1;perform count(*)from clara.metric_input_snapshot_contributions where snapshot_id=ctx.snapshot_id;perform count(*)from clara.metric_input_snapshot_open_items where snapshot_id=ctx.snapshot_id;perform count(*)from clara.metric_input_snapshot_allocations where snapshot_id=ctx.snapshot_id;perform count(*)from clara.metric_input_snapshot_samples where snapshot_id=ctx.snapshot_id;v:=clara._metric_recheck_node_v1(mc.client_id,ctx.snapshot_id,ctx.id,root_period,root_ast,allow_neg,avg_key,null);if v.status='ok'then factor:=power(10::numeric,scale);q:=div(abs(v.numerator)*factor,v.denominator);rem:=mod(abs(v.numerator)*factor,v.denominator);if rem*2>=v.denominator then q:=q+1;end if;shown:=to_char((case when v.numerator<0 then-q else q end)/factor,'FM999999999999999999999999999999999999999999999999990'||case when scale>0 then'.'||repeat('0',scale)else''end);end if;select reason_key into expected_reason from clara.metric_na_reason_versions where id=expected.na_reason_version_id;select coalesce(array_agg(account_set_version_id order by account_set_version_id),'{}')into expected_account_sets from clara.metric_cell_account_sets where cell_id=expected.id;select coalesce(array_agg(constant_version_id order by constant_version_id),'{}')into expected_constants from clara.metric_cell_constants where cell_id=expected.id;select coalesce(array_agg(entry_id order by entry_id),'{}')into expected_entries from clara.metric_cell_entries where cell_id=expected.id;select coalesce(array_agg(document_id order by document_id),'{}')into expected_documents from clara.metric_cell_documents where cell_id=expected.id;expected_evaluator_inputs:=expected.inputs-array['schema','provenance_not_applicable','normalized_provenance','composition'];expected_signs:=coalesce(expected_evaluator_inputs->'sign_normalizations','[]'::jsonb);same:=expected.definition_version_id is not distinct from mc.definition_version_id and expected.evaluation_context_id=mc.evaluation_context_id and v.status=expected.cell_status and v.reason_key is not distinct from expected_reason and(case when v.status='ok'then v.numerator end)is not distinct from expected.exact_numerator and(case when v.status='ok'then v.denominator end)is not distinct from expected.exact_denominator and expected.displayed_scale is not distinct from(case when v.status='ok'then scale end)and shown is not distinct from expected.displayed_text and array(select x from unnest(v.account_set_version_ids)x order by x)is not distinct from expected_account_sets and array(select x from unnest(v.constant_version_ids)x order by x)is not distinct from expected_constants and array(select x from unnest(v.entry_ids)x order by x)is not distinct from expected_entries and array(select x from unnest(v.document_ids)x order by x)is not distinct from expected_documents and coalesce(v.inputs,'{}'::jsonb)is not distinct from expected_evaluator_inputs;select id into ev from clara.evaluator_versions where evaluator_name='assess_metric_cell_independent'and version=1 and firm_id is null and deployed;if ev is null then raise exception 'independent metric evaluator is not deployed'using errcode='CLR10',detail='{"reason":"evaluator_undeployed"}';end if;insert into clara.metric_cell_assessments(firm_id,client_id,cell_id,evaluator_version_id,observed_status,observed_reason_key,observed_numerator,observed_denominator,matches,assessed_by,details)values(c.firm,mc.client_id,mc.id,ev,v.status,v.reason_key,case when v.status='ok'then v.numerator end,case when v.status='ok'then v.denominator end,same,c.actor,jsonb_build_object('source','independent immutable primitive facts plus independently resolved selector identity','expected_cell_id',expected.id,'observed_displayed_scale',case when v.status='ok'then scale end,'observed_displayed_text',shown,'observed_account_set_version_ids',v.account_set_version_ids,'observed_constant_version_ids',v.constant_version_ids,'observed_entry_ids',v.entry_ids,'observed_document_ids',v.document_ids,'observed_evaluator_inputs',coalesce(v.inputs,'{}'::jsonb),'observed_sign_normalizations',coalesce(v.inputs->'sign_normalizations','[]'::jsonb),'expected_evaluator_inputs',expected_evaluator_inputs,'expected_account_set_version_ids',expected_account_sets,'expected_constant_version_ids',expected_constants,'expected_entry_ids',expected_entries,'expected_document_ids',expected_documents,'expected_sign_normalizations',expected_signs,'expected_status',expected.cell_status,'expected_reason_key',expected_reason,'expected_exact_numerator',expected.exact_numerator,'expected_exact_denominator',expected.exact_denominator,'mismatch',not same))returning id into aid;perform clara._audit(c.firm,c.actor,null,null,'assess_metric_cell_independent_v1',null,jsonb_build_object('cell_id',mc.id,'assessment_id',aid,'op_key',p_op_key));return clara._finish_op(c.firm,'assess_metric_cell_independent_v1',p_op_key,jsonb_build_object('assessment_id',aid,'matches',same));end$$;
revoke all on function clara.assess_metric_cell_independent_v1(uuid,uuid,text)from public;grant execute on function clara.assess_metric_cell_independent_v1(uuid,uuid,text)to clara_authenticated;

-- A30b evaluation-attempt receipts. The writer is authenticated-human-only: delta v1 grants no
-- runtime or wake identity here and synthesizes no JWT claims. It is called AFTER the failed
-- evaluation's transaction has rolled back, so the four cap numbers are MEASURED here, in this
-- transaction, never taken from the caller's arithmetic; a 57014 is recorded as a cancellation
-- carrying its configured timeout and diagnostics, never as a deterministic cost_exceeded. The
-- natural key (firm, client, run, attempt_key) is the idempotency key: re-recording the same
-- attempt returns the one existing row. It is deliberately NOT a member of any evaluator closure --
-- it produces no metric number and must stay repairable without recutting a frozen evaluator.
create function clara.record_metric_evaluation_attempt_v1(p_client uuid,p_run_id uuid,p_outcome_class text,p_entrypoint text,p_definition_version_ids uuid[],p_attempt_key text,p_configured_statement_timeout text,p_diagnostics jsonb)returns jsonb language plpgsql security definer set search_path=clara,pg_temp as $attempt$
declare c record;existing_count int;new_required int;projected int;rid uuid;unknown_defs uuid[];
begin
 c:=clara._human_ctx(clara.role_rank('bookkeeper'));
 perform 1 from clara.clients where id=p_client and firm_id=c.firm;if not found then raise exception 'client not found in your firm'using errcode='CLR11';end if;
 if p_run_id is null or nullif(btrim(coalesce(p_attempt_key,'')),'')is null then raise exception 'evaluation-attempt receipt needs its run and attempt identity'using errcode='CLR10',detail='{"reason":"invalid_request","class":"attempt_identity","constraint":"nonempty_nonnull"}';end if;
 if p_outcome_class is distinct from'cap_refusal'and p_outcome_class is distinct from'cancellation'then raise exception 'evaluation-attempt outcome class is outside the closed set'using errcode='CLR10',detail='{"reason":"invalid_request","class":"outcome_class"}';end if;
 if p_entrypoint is distinct from'clara.evaluate_metric_v1(uuid,uuid,uuid[],uuid,uuid)'and p_entrypoint is distinct from'clara.evaluate_fs_pack_v1(uuid,uuid[],uuid[],uuid,uuid)'then raise exception 'evaluation-attempt entrypoint is not a registered metric evaluation entrypoint'using errcode='CLR10',detail='{"reason":"invalid_request","class":"entrypoint"}';end if;
 if p_diagnostics is not null and jsonb_typeof(p_diagnostics)<>'object'then raise exception 'evaluation-attempt diagnostics must be an object'using errcode='CLR10',detail='{"reason":"invalid_request","class":"diagnostics"}';end if;
 select id into rid from clara.metric_evaluation_attempt_receipts where firm_id=c.firm and client_id=p_client and run_id=p_run_id and attempt_key=p_attempt_key;
 if rid is not null then return(select jsonb_build_object('receipt_id',r.id,'recorded',false,'outcome_class',r.outcome_class,'sqlstate',r.sqlstate,'existing_cell_count',r.existing_cell_count,'new_required_cell_count',r.new_required_cell_count,'projected_cell_count',r.projected_cell_count,'cell_limit',r.cell_limit,'configured_statement_timeout',r.configured_statement_timeout)from clara.metric_evaluation_attempt_receipts r where r.id=rid);end if;
 if p_outcome_class='cap_refusal'then
  if p_definition_version_ids is null or cardinality(p_definition_version_ids)=0 or array_position(p_definition_version_ids,null)is not null or cardinality(array(select distinct x from unnest(p_definition_version_ids)x))<>cardinality(p_definition_version_ids)then raise exception 'a cap-refusal receipt needs the exact nonempty unique definition set the attempt requested'using errcode='CLR10',detail='{"reason":"invalid_request","class":"definition_versions","constraint":"nonempty_nonnull_unique"}';end if;
  -- ARITY BINDS TO THE NAMED ENTRYPOINT. Without this a caller can label a two-definition attempt
  -- 'scalar' and mint an immutable receipt for a breach clara.evaluate_metric_v1 could never produce.
  if(p_entrypoint='clara.evaluate_metric_v1(uuid,uuid,uuid[],uuid,uuid)'and cardinality(p_definition_version_ids)<>1)then raise exception 'the scalar entrypoint evaluates exactly one definition per attempt'using errcode='CLR10',detail=jsonb_build_object('reason','invalid_request','class','definition_versions','constraint','scalar_arity_one','supplied',cardinality(p_definition_version_ids))::text;end if;
  -- EVERY SUPPLIED DEFINITION MUST BE ONE THE EVALUATING ENTRYPOINT WOULD HAVE ACCEPTED: approved, this
  -- firm's or the product's, and hash-consistent -- the same admission clara.evaluate_fs_pack_v1
  -- applies. A fabricated or unapproved id cannot buy a receipt for a breach that never happened.
  select coalesce(array_agg(u.definition_version_id order by u.definition_version_id),'{}')into unknown_defs from unnest(p_definition_version_ids)u(definition_version_id)where not exists(select 1 from clara.metric_definition_versions v join clara.metric_definitions d on d.id=v.definition_id and d.firm_id is not distinct from v.firm_id where v.id=u.definition_version_id and(v.firm_id is null or v.firm_id=c.firm)and v.state in('canonical','firm_approved')and v.approved_formula_sha256=v.formula_sha256);
  if cardinality(unknown_defs)>0 then raise exception 'a cap-refusal receipt names a definition this firm could not have evaluated'using errcode='CLR11',detail=jsonb_build_object('reason','definition_unavailable','class','definition_versions','unavailable',to_jsonb(unknown_defs),'fix','name only approved definition versions available to this client''s firm')::text;end if;
  select count(*)::int into existing_count from clara.metric_cells where firm_id=c.firm and run_id=p_run_id;
  -- MEASURED, deduped, in this writer's own transaction: the number of supplied definitions that
  -- have NO existing cell on this (client, run). Already-evaluated definitions collapse out.
  select count(*)::int into new_required from unnest(array(select distinct x from unnest(p_definition_version_ids)x))u(definition_version_id)where not exists(select 1 from clara.metric_cells mc where mc.firm_id=c.firm and mc.client_id=p_client and mc.run_id=p_run_id and mc.definition_version_id=u.definition_version_id);
  projected:=existing_count+new_required;
  if projected<=5000 then raise exception 'the measured attempt does not breach the cells-per-run ceiling'using errcode='CLR10',detail=jsonb_build_object('reason','scope_mismatch','class','cap_boundary_absent','existing_count',existing_count,'new_required',new_required,'projected_count',projected,'limit',5000,'fix','record a cap refusal only for an attempt whose own measured projection exceeds the ceiling')::text;end if;
  insert into clara.metric_evaluation_attempt_receipts(firm_id,client_id,run_id,attempt_key,outcome_class,entrypoint,sqlstate,existing_cell_count,new_required_cell_count,projected_cell_count,cell_limit,diagnostics,recorded_by)values(c.firm,p_client,p_run_id,p_attempt_key,'cap_refusal',p_entrypoint,'CLR10',existing_count,new_required,projected,5000,coalesce(p_diagnostics,'{}'::jsonb)||jsonb_build_object('counts_measured_by','clara.record_metric_evaluation_attempt_v1','requested_count',cardinality(p_definition_version_ids)),c.actor)on conflict(firm_id,client_id,run_id,attempt_key)do nothing returning id into rid;
 else
  -- A POSITIVE duration, not merely a parseable one: '0' means "no timeout was configured", which
  -- cannot be the thing that cancelled the call, and a receipt asserting it would be false.
  if nullif(btrim(coalesce(p_configured_statement_timeout,'')),'')is null or btrim(p_configured_statement_timeout)!~'^[0-9]+\s*(us|ms|s|min|h|d)?$'or coalesce(substring(btrim(p_configured_statement_timeout)from'^[0-9]+')::bigint,0)<=0 then raise exception 'a cancellation receipt must carry the POSITIVE statement timeout the cancelled call was configured with'using errcode='CLR10',detail='{"reason":"invalid_request","class":"configured_statement_timeout","constraint":"positive_postgres_statement_timeout_text"}';end if;
  -- Diagnostics are REQUIRED and non-empty for this class. The cap class can stand on its own four
  -- measured numbers; a cancellation has none, so the caller's account of what was cancelled is the
  -- only content the receipt carries, and an empty one would be a receipt asserting nothing.
  if p_diagnostics is null or p_diagnostics='{}'::jsonb then raise exception 'a cancellation receipt must carry diagnostics describing the cancelled attempt'using errcode='CLR10',detail='{"reason":"invalid_request","class":"diagnostics","constraint":"nonempty_object"}';end if;
  insert into clara.metric_evaluation_attempt_receipts(firm_id,client_id,run_id,attempt_key,outcome_class,entrypoint,sqlstate,configured_statement_timeout,diagnostics,recorded_by)values(c.firm,p_client,p_run_id,p_attempt_key,'cancellation',p_entrypoint,'57014',btrim(p_configured_statement_timeout),coalesce(p_diagnostics,'{}'::jsonb)||jsonb_build_object('recorded_by','clara.record_metric_evaluation_attempt_v1','configured_statement_timeout_source','caller_reported','cancellation_is_not_cost_exceeded',true),c.actor)on conflict(firm_id,client_id,run_id,attempt_key)do nothing returning id into rid;
 end if;
 -- THE CONCURRENT LOSER. ON CONFLICT DO NOTHING is atomic where a unique_violation handler was not:
 -- the handler re-selected under the SAME transaction snapshot, so at REPEATABLE READ or
 -- SERIALIZABLE the loser saw no row and returned SQL NULL -- no receipt and no error, the worst of
 -- both. Here the loser re-reads; if its pinned snapshot still cannot see the winner's row it says
 -- so with a RETRYABLE serialization-class error naming the retry, and never returns null.
 if rid is null then
  select id into rid from clara.metric_evaluation_attempt_receipts where firm_id=c.firm and client_id=p_client and run_id=p_run_id and attempt_key=p_attempt_key;
  if rid is null then raise exception 'a concurrent recording of this attempt is not visible in this transaction snapshot'using errcode='40001',detail='{"reason":"concurrent_attempt_receipt","fix":"retry the recording in a new transaction; the winning receipt is already durable"}';end if;
  return(select jsonb_build_object('receipt_id',r.id,'recorded',false,'outcome_class',r.outcome_class,'sqlstate',r.sqlstate,'existing_cell_count',r.existing_cell_count,'new_required_cell_count',r.new_required_cell_count,'projected_cell_count',r.projected_cell_count,'cell_limit',r.cell_limit,'configured_statement_timeout',r.configured_statement_timeout)from clara.metric_evaluation_attempt_receipts r where r.id=rid);
 end if;
 perform clara._audit(c.firm,c.actor,null,null,'record_metric_evaluation_attempt_v1',null,jsonb_build_object('client',p_client,'run_id',p_run_id,'attempt_key',p_attempt_key,'outcome_class',p_outcome_class,'receipt_id',rid));
 return(select jsonb_build_object('receipt_id',r.id,'recorded',true,'outcome_class',r.outcome_class,'sqlstate',r.sqlstate,'existing_cell_count',r.existing_cell_count,'new_required_cell_count',r.new_required_cell_count,'projected_cell_count',r.projected_cell_count,'cell_limit',r.cell_limit,'configured_statement_timeout',r.configured_statement_timeout)from clara.metric_evaluation_attempt_receipts r where r.id=rid);
end $attempt$;
revoke all on function clara.record_metric_evaluation_attempt_v1(uuid,uuid,text,text,uuid[],text,text,jsonb)from public;grant execute on function clara.record_metric_evaluation_attempt_v1(uuid,uuid,text,text,uuid[],text,text,jsonb)to clara_authenticated;

