-- search_path makes pg_get_functiondef's qualification stable for both registration and verification.
set local search_path=pg_catalog,pg_temp;
do $freeze$ declare e uuid;h bytea;begin select sha256(convert_to(string_agg(encode(sha256(convert_to(pg_get_functiondef(to_regprocedure(s))::text,'UTF8')),'hex'),''order by o),'UTF8'))into h from(values(0,'clara.evaluate_metric_v1(uuid,uuid,uuid[],uuid,uuid)'),(1,'clara._metric_eval_node_v1(uuid,uuid,uuid,uuid,jsonb,boolean,text,date)'),(2,'clara.validate_metric_ast_v1(jsonb)'),(3,'clara._validate_metric_node_v1(jsonb,integer)'),(4,'clara._metric_selector_account_ids(uuid,jsonb)'),(5,'clara._metric_input_dataset_v1(uuid,uuid,uuid[])'),(6,'clara._metric_context_sha256_v1(uuid,uuid[],uuid,uuid,uuid,uuid,bytea,text)'),(7,'clara._metric_resolved_inputs_sha256_v1(bytea,uuid[],uuid,uuid,uuid,bytea,uuid[],uuid[],uuid,uuid,uuid,text)'),(8,'clara._hash(jsonb)'),(9,'clara.evaluate_fs_pack_v1(uuid,uuid[],uuid[],uuid,uuid)'))m(o,s);insert into clara.evaluator_versions(evaluator_name,version,entrypoint_signature,closure_sha256,migration_version,deployed)values('evaluate_metric',1,'clara.evaluate_metric_v1(uuid,uuid,uuid[],uuid,uuid)',h,'0059_wave_e_delta_metrics_behavior',false)returning id into e;insert into clara.evaluator_version_members(evaluator_version_id,ordinal,member_signature,body_sha256,firm_id)select e,o,s,sha256(convert_to(pg_get_functiondef(to_regprocedure(s))::text,'UTF8')),null::uuid from(values(0,'clara.evaluate_metric_v1(uuid,uuid,uuid[],uuid,uuid)'),(1,'clara._metric_eval_node_v1(uuid,uuid,uuid,uuid,jsonb,boolean,text,date)'),(2,'clara.validate_metric_ast_v1(jsonb)'),(3,'clara._validate_metric_node_v1(jsonb,integer)'),(4,'clara._metric_selector_account_ids(uuid,jsonb)'),(5,'clara._metric_input_dataset_v1(uuid,uuid,uuid[])'),(6,'clara._metric_context_sha256_v1(uuid,uuid[],uuid,uuid,uuid,uuid,bytea,text)'),(7,'clara._metric_resolved_inputs_sha256_v1(bytea,uuid[],uuid,uuid,uuid,bytea,uuid[],uuid[],uuid,uuid,uuid,text)'),(8,'clara._hash(jsonb)'),(9,'clara.evaluate_fs_pack_v1(uuid,uuid[],uuid[],uuid,uuid)'))m(o,s);select sha256(convert_to(string_agg(encode(sha256(convert_to(pg_get_functiondef(to_regprocedure(s))::text,'UTF8')),'hex'),''order by o),'UTF8'))into h from(values(0,'clara.assess_metric_cell_independent_v1(uuid,uuid,text)'),(1,'clara._metric_recheck_node_v1(uuid,uuid,uuid,uuid,jsonb,boolean,text,date)'))m(o,s);insert into clara.evaluator_versions(evaluator_name,version,entrypoint_signature,closure_sha256,migration_version,deployed)values('assess_metric_cell_independent',1,'clara.assess_metric_cell_independent_v1(uuid,uuid,text)',h,'0059_wave_e_delta_metrics_behavior',false)returning id into e;insert into clara.evaluator_version_members(evaluator_version_id,ordinal,member_signature,body_sha256,firm_id)select e,o,s,sha256(convert_to(pg_get_functiondef(to_regprocedure(s))::text,'UTF8')),null::uuid from(values(0,'clara.assess_metric_cell_independent_v1(uuid,uuid,text)'),(1,'clara._metric_recheck_node_v1(uuid,uuid,uuid,uuid,jsonb,boolean,text,date)'))m(o,s);end$freeze$;

create function clara.verify_evaluator_freeze()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,pg_temp as $$declare r record;total int;aggregate_hash bytea;member_count int;entry_count int;begin for r in select * from clara.evaluator_versions order by evaluator_name,version loop if to_regprocedure(r.entrypoint_signature)is null then raise exception 'evaluator freeze signature absent: %',r.entrypoint_signature using errcode='CLR10';end if;select count(*),count(*)filter(where member_signature=r.entrypoint_signature),sha256(convert_to(string_agg(encode(body_sha256,'hex'),''order by ordinal),'UTF8'))into member_count,entry_count,aggregate_hash from clara.evaluator_version_members where evaluator_version_id=r.id;if member_count=0 or entry_count<>1 or aggregate_hash is distinct from r.closure_sha256 then raise exception 'evaluator freeze closure incomplete: %',r.evaluator_name using errcode='CLR10';end if;if exists(select 1 from clara.evaluator_version_members m where m.evaluator_version_id=r.id and(to_regprocedure(m.member_signature)is null or m.body_sha256 is distinct from sha256(convert_to(pg_get_functiondef(to_regprocedure(m.member_signature))::text,'UTF8'))))then raise exception 'evaluator freeze mismatch: %',r.evaluator_name using errcode='CLR10';end if;end loop;select count(*)into total from clara.evaluator_versions;if total<2 or not exists(select 1 from clara.evaluator_versions where evaluator_name='evaluate_metric'and version=1)or not exists(select 1 from clara.evaluator_versions where evaluator_name='assess_metric_cell_independent'and version=1)then raise exception 'evaluator freeze required v1 closures are incomplete'using errcode='CLR10';end if;return jsonb_build_object('ok',true,'verified_deployed',(select count(*)from clara.evaluator_versions where deployed),'verified_registered',total);end$$;
revoke all on function clara.verify_evaluator_freeze()from public;grant execute on function clara.verify_evaluator_freeze()to clara_authenticated;
reset role;
do $tail$ declare b text;n int;primary_members int;checker_members int;begin if current_user<>(select v from _delta_behavior_pre where k='session_user')or current_role<>(select v from _delta_behavior_pre where k='current_user')then raise exception 'delta behaviour tail: role not reset (user %, role %)',current_user,current_role using errcode='CLR10';end if;select string_agg(pg_get_functiondef(p.oid),E'\n')into b from pg_proc p where p.pronamespace='clara'::regnamespace and(p.proname like'evaluate_metric_v%'or p.proname='evaluate_fs_pack_v1'or p.proname like'%metric%valid%'or p.proname in('assess_metric_cell_independent_v1','_metric_recheck_node_v1','record_metric_evaluation_attempt_v1'));if b~*'\m(float4|float8|real)\M|\mdouble\s+precision\M|::\s*float'then raise exception 'delta behaviour tail: floating path found'using errcode='CLR10';end if;if(pg_get_functiondef('clara.assess_metric_cell_independent_v1(uuid,uuid,text)'::regprocedure)||pg_get_functiondef('clara._metric_recheck_node_v1(uuid,uuid,uuid,uuid,jsonb,boolean,text,date)'::regprocedure))~*'evaluate_metric_v1\s*\(|_metric_eval_node_v1\s*\(|validate_metric_ast_v1\s*\(|_validate_metric_node_v1\s*\(|_normalize_metric_node_v1\s*\(|_metric_selector_account_ids\s*\(|_metric_input_dataset_v1\s*\(|_metric_context_sha256_v1\s*\(|_metric_resolved_inputs_sha256_v1\s*\(|(from|join)\s+(clara\.)?(journal_entries|journal_lines|open_items|open_item_allocations|period_snapshots)\M|trial_balance_as_of\s*\('then raise exception 'delta behaviour tail: E6 shares a primary or live-books path'using errcode='CLR10';end if;select count(*)into n from clara.metric_primitives;if n<>11 then raise exception 'delta behaviour tail: primitive closure %, expected 11',n using errcode='CLR10';end if;select count(*)filter(where e.evaluator_name='evaluate_metric'),count(*)filter(where e.evaluator_name='assess_metric_cell_independent')into primary_members,checker_members from clara.evaluator_versions e join clara.evaluator_version_members m on m.evaluator_version_id=e.id;if primary_members<>10 or checker_members<>2 then raise exception 'delta behaviour tail: closure census primary %, checker %, expected 10/2',primary_members,checker_members using errcode='CLR10';end if;perform clara.verify_evaluator_freeze();
 if to_regprocedure('clara.record_metric_evaluation_attempt_v1(uuid,uuid,text,text,uuid[],text,text,jsonb)')is null or not exists(select 1 from pg_proc f where f.oid='clara.record_metric_evaluation_attempt_v1(uuid,uuid,text,text,uuid[],text,text,jsonb)'::regprocedure and f.prosecdef and f.proconfig@>array['search_path=clara, pg_temp'])then raise exception 'delta behaviour tail: the A30b attempt-receipt writer is absent or unpinned'using errcode='CLR10';end if;
 select count(*)into n from clara.metric_evaluation_attempt_receipts;if n<>0 then raise exception 'delta behaviour tail: delta seeds % evaluation-attempt receipt(s), expected 0',n using errcode='CLR10';end if;
 raise notice 'delta behaviour OK: closed 11-node algebra; ten canonical formulas; exact rationals; immutable samples; exact calendar prior; period-effective N/A reasons anchored on the root period; fail-closed explicit selector exactness; one root rounding; ordered atomic pack driver; independent four-family E6 plus direct current-CoA selector drift identity and definitionless composition replay; A30b attempt-receipt writer registered, seeded 0; frozen closures 10/2; owner-neutral tail.';end$tail$;
